import {
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Patch,
  Post,
  Query,
  UseGuards,
} from '@nestjs/common';
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import { AdminService } from './admin.service';
import { UsersService } from '../users/users.service';
import { PrismaService } from '../prisma/prisma.service';
import { JwtAuthGuard } from '../auth/jwt-auth.guard';
import { PermissionsGuard } from '../auth/permissions.guard';
import { Permissions } from '../auth/permissions.decorator';
import { CurrentUser } from '../auth/current-user.decorator';
import type { Actor } from '../common/document-policy';
import { CreateUserDto, UpdateUserDto } from './dto/create-user.dto';
import { BadRequestException } from '@nestjs/common';

@Controller('admin')
@UseGuards(JwtAuthGuard, PermissionsGuard)
export class AdminController {
  constructor(
    private readonly adminService: AdminService,
    private readonly usersService: UsersService,
    private readonly prisma: PrismaService,
  ) {}
  @Get('settings')
  getSettings() {
    const p = path.join(process.cwd(), 'uploads/settings.json');
    return fs.existsSync(p)
      ? JSON.parse(fs.readFileSync(p, 'utf8'))
      : { companyName: 'บริษัท นิสซุย (ประเทศไทย) จำกัด', companyAddress: '' };
  }
  @Post('settings')
  @Permissions('config.access:edit', 'config.role_management:edit')
  async saveSettings(
    @Body() body: { companyName?: string; companyAddress?: string },
    @CurrentUser() actor: Actor,
  ) {
    if (
      !body.companyName?.trim() ||
      body.companyName.length > 500 ||
      (body.companyAddress?.length ?? 0) > 5000
    )
      throw new BadRequestException('ข้อมูลบริษัทไม่ถูกต้อง');
    const before = this.getSettings(),
      settings = {
        companyName: body.companyName.trim(),
        companyAddress: body.companyAddress ?? '',
      };
    const directory = path.join(process.cwd(), 'uploads');
    fs.mkdirSync(directory, { recursive: true });
    const destination = path.join(directory, 'settings.json'),
      temp = path.join(directory, `settings-${crypto.randomUUID()}.tmp`);
    fs.writeFileSync(temp, JSON.stringify(settings, null, 2));
    fs.renameSync(temp, destination);
    await this.prisma.auditLog.create({
      data: {
        user_id: actor.id,
        action: 'Edit',
        module: 'Settings',
        details: { oldState: before, newState: settings, extra: {} },
      },
    });
    return { success: true };
  }
  @Get('users')
  @Permissions('config.user_management:view', 'config.role_management:view')
  users() {
    return this.adminService.getUsers();
  }
  @Post('users')
  @Permissions('config.user_management:create')
  createUser(@Body() dto: CreateUserDto, @CurrentUser() actor: Actor) {
    return this.adminService.createUser(dto, actor);
  }
  @Patch('users/:id')
  @Permissions('config.user_management:edit')
  updateUser(
    @Param('id') id: string,
    @Body() dto: UpdateUserDto,
    @CurrentUser() actor: Actor,
  ) {
    return this.adminService.updateUser(id, dto, actor);
  }
  @Patch('users/:id/toggle-active')
  @Permissions('config.user_management:edit')
  toggleUser(@Param('id') id: string, @CurrentUser() actor: Actor) {
    return this.adminService.toggleUserActive(id, actor);
  }
  @Post('users/:id/reset-password')
  @Permissions('config.user_management:edit')
  resetUser(
    @Param('id') id: string,
    @Body() body: { password_hash: string },
    @CurrentUser() actor: Actor,
  ) {
    return this.adminService.resetUserPassword(id, body.password_hash, actor);
  }
  @Get('roles')
  @Permissions(
    'config.role_management:view',
    'config.user_management:view',
    'masterdata.access:view',
  )
  roles() {
    return this.adminService.getRoles();
  }
  @Get('roles/:id')
  @Permissions('config.role_management:view')
  role(@Param('id') id: string) {
    return this.adminService.getRoleById(id);
  }
  @Post('roles')
  @Permissions('config.role_management:create')
  createRole(@Body('name') name: string, @CurrentUser() actor: Actor) {
    return this.adminService.createRole(name, actor);
  }
  @Patch('roles/:id')
  @Permissions('config.role_management:edit')
  updateRole(
    @Param('id') id: string,
    @Body()
    dto: {
      name?: string;
      is_active?: boolean;
      permissions?: { module: string; action: string }[];
    },
    @CurrentUser() actor: Actor,
  ) {
    return this.adminService.updateRole(id, dto, actor);
  }
  @Delete('roles/:id')
  @Permissions('config.role_management:delete')
  deleteRole(@Param('id') id: string, @CurrentUser() actor: Actor) {
    return this.adminService.deleteRole(id, actor);
  }
  @Get('departments')
  @Permissions('masterdata.access:view', 'config.user_management:view')
  departments() {
    return this.adminService.getDepartments();
  }
  @Post('departments')
  @Permissions('masterdata.access:edit', 'masterdata.departments:create')
  createDepartment(@Body() dto: { name: string }, @CurrentUser() actor: Actor) {
    return this.adminService.createDepartment(dto.name, actor);
  }
  @Patch('departments/:id')
  @Permissions('masterdata.access:edit', 'masterdata.departments:edit')
  updateDepartment(
    @Param('id') id: string,
    @Body() dto: { name?: string; is_active?: boolean },
    @CurrentUser() actor: Actor,
  ) {
    return this.adminService.updateDepartment(id, dto, actor);
  }
  @Delete('departments/:id')
  @Permissions('masterdata.access:delete', 'masterdata.departments:delete')
  deleteDepartment(@Param('id') id: string, @CurrentUser() actor: Actor) {
    return this.adminService.deleteDepartment(id, actor);
  }
  @Get('positions')
  @Permissions('masterdata.access:view', 'config.user_management:view')
  positions() {
    return this.adminService.getPositions();
  }
  @Post('positions')
  @Permissions('masterdata.access:edit', 'masterdata.positions:create')
  createPosition(
    @Body() dto: { name: string; level?: string },
    @CurrentUser() actor: Actor,
  ) {
    return this.adminService.createPosition(dto, actor);
  }
  @Patch('positions/:id')
  @Permissions('masterdata.access:edit', 'masterdata.positions:edit')
  updatePosition(
    @Param('id') id: string,
    @Body() dto: { name?: string; level?: string; is_active?: boolean },
    @CurrentUser() actor: Actor,
  ) {
    return this.adminService.updatePosition(id, dto, actor);
  }
  @Delete('positions/:id')
  @Permissions('masterdata.access:delete', 'masterdata.positions:delete')
  deletePosition(@Param('id') id: string, @CurrentUser() actor: Actor) {
    return this.adminService.deletePosition(id, actor);
  }
  @Get('document-types')
  @Permissions('masterdata.access:view')
  types() {
    return this.adminService.getDocumentTypes();
  }
  @Post('document-types')
  @Permissions('masterdata.access:edit', 'masterdata.doc_types:create')
  createType(
    @Body() dto: { type_name: string; prefix: string },
    @CurrentUser() actor: Actor,
  ) {
    return this.adminService.createDocumentType(dto, actor);
  }
  @Patch('document-types/:id')
  @Permissions('masterdata.access:edit', 'masterdata.doc_types:edit')
  updateType(
    @Param('id') id: string,
    @Body() dto: { type_name?: string; prefix?: string; is_active?: boolean },
    @CurrentUser() actor: Actor,
  ) {
    return this.adminService.updateDocumentType(id, dto, actor);
  }
  @Get('workflows')
  @Permissions('masterdata.access:view')
  workflows() {
    return this.adminService.getApprovalWorkflows();
  }
  @Patch('workflows/:id')
  @Permissions('masterdata.access:edit', 'masterdata.workflow:edit')
  workflow(
    @Param('id') id: string,
    @Body() dto: { levels?: number; steps?: string[]; is_active?: boolean },
    @CurrentUser() actor: Actor,
  ) {
    return this.adminService.updateApprovalWorkflow(id, dto, actor);
  }
  @Get('signatures')
  @Permissions('masterdata.access:view', 'masterdata.signatures:view')
  signatures() {
    return this.adminService.getSignatures();
  }
  @Patch('signatures/:id')
  @Permissions(
    'masterdata.access:edit',
    'masterdata.signatures:edit',
    'masterdata.signatures:create',
  )
  setSignature(
    @Param('id') id: string,
    @Body() body: { imageUrl: string | null },
    @CurrentUser() actor: Actor,
  ) {
    return this.usersService.setUserSignature(id, body.imageUrl, actor);
  }
  @Get('approval-matrix')
  @Permissions('masterdata.access:view')
  matrix() {
    return this.adminService.getApprovalMatrix();
  }
  @Post('approval-matrix')
  @Permissions('masterdata.access:edit', 'masterdata.workflow:edit')
  createMatrix(
    @Body()
    dto: {
      document_type_id: string;
      step_order: number;
      approver_role_id: string;
    },
    @CurrentUser() actor: Actor,
  ) {
    return this.adminService.createApprovalMatrixStep(dto, actor);
  }
  @Patch('approval-matrix/:id')
  @Permissions('masterdata.access:edit', 'masterdata.workflow:edit')
  updateMatrix(
    @Param('id') id: string,
    @Body() dto: { step_order?: number; approver_role_id?: string },
    @CurrentUser() actor: Actor,
  ) {
    return this.adminService.updateApprovalMatrixStep(id, dto, actor);
  }
  @Get('running-numbers')
  @Permissions('masterdata.access:view')
  numbers() {
    return this.adminService.getRunningNumbers();
  }
  @Patch('running-numbers/:id')
  @Permissions('masterdata.access:edit', 'masterdata.running_numbers:edit')
  updateNumber(
    @Param('id') id: string,
    @Body() dto: Parameters<AdminService['updateRunningNumber']>[1],
    @CurrentUser() actor: Actor,
  ) {
    return this.adminService.updateRunningNumber(id, dto, actor);
  }
  @Get('audit-logs')
  @Permissions('auditlog.access:view')
  logs(
    @Query('search') search?: string,
    @Query('action') action?: string,
    @Query('dateFrom') dateFrom?: string,
    @Query('dateTo') dateTo?: string,
  ) {
    return this.adminService.getAuditLogs(search, action, dateFrom, dateTo);
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
  ConflictException,
} from '@nestjs/common';
import * as bcrypt from 'bcrypt';
import { Prisma, AuditAction } from '@prisma/client';
import { PrismaService } from '../prisma/prisma.service';
import { EncryptionService } from '../common/encryption/encryption.service';
import { CreateUserDto } from './dto/create-user.dto';
import {
  Actor,
  lockEntity,
  jsonSnapshot,
  safeUserSelect,
} from '../common/document-policy';

@Injectable()
export class AdminService {
  constructor(
    private prisma: PrismaService,
    private encryption: EncryptionService,
  ) {}
  private async audit(
    tx: Prisma.TransactionClient,
    actor: Actor,
    module: string,
    target: string,
    oldState: unknown,
    newState: unknown,
    action: AuditAction = 'Edit',
  ) {
    await tx.auditLog.create({
      data: {
        user_id: actor.id,
        action,
        module,
        target_id: target,
        details: {
          oldState: jsonSnapshot(oldState),
          newState: jsonSnapshot(newState),
          extra: {},
        },
      },
    });
  }
  async getUsers() {
    const list = await this.prisma.user.findMany({
      where: { is_deleted: false },
      select: {
        ...safeUserSelect,
        is_active: true,
        created_at: true,
        role_id: true,
        department_id: true,
        position_id: true,
      },
      orderBy: { created_at: 'desc' },
    });
    return list.map((u) => ({
      ...u,
      department: u.department?.name ?? '',
      position: u.position?.name ?? '',
      role: u.role?.name ?? '',
    }));
  }
  private async references(
    tx: Prisma.TransactionClient,
    dto: Partial<CreateUserDto>,
  ) {
    if (
      dto.role_id &&
      !(await tx.role.findFirst({
        where: { id: dto.role_id, is_active: true },
      }))
    )
      throw new BadRequestException('ไม่พบบทบาทที่ใช้งาน');
    if (
      dto.department_id &&
      !(await tx.department.findFirst({
        where: { id: dto.department_id, is_active: true },
      }))
    )
      throw new BadRequestException('ไม่พบแผนกที่ใช้งาน');
    if (
      dto.position_id &&
      !(await tx.position.findFirst({
        where: { id: dto.position_id, is_active: true },
      }))
    )
      throw new BadRequestException('ไม่พบตำแหน่งที่ใช้งาน');
  }
  async createUser(dto: CreateUserDto, actor: Actor) {
    if (!dto.password || !dto.role_id || !dto.department_id)
      throw new BadRequestException('กรุณาระบุรหัสผ่าน บทบาท และแผนก');
    const hash = await bcrypt.hash(dto.password, 10);
    return this.prisma.$transaction(async (tx) => {
      await this.references(tx, dto);
      const user = await tx.user.create({
        data: {
          username: dto.username.trim(),
          email: dto.email.trim(),
          first_name: dto.first_name.trim(),
          last_name: dto.last_name.trim(),
          role_id: dto.role_id,
          department_id: dto.department_id,
          position_id: dto.position_id,
          is_active: dto.is_active ?? true,
          password_hash: hash,
        },
        select: safeUserSelect,
      });
      await this.audit(tx, actor, 'User', user.id, {}, user, 'Upload');
      return user;
    });
  }
  async toggleUserActive(id: string, actor: Actor) {
    return this.prisma.$transaction(async (tx) => {
      await lockEntity(tx, `user:${id}`);
      const user = await tx.user.findUnique({
        where: { id },
        select: { id: true, is_active: true },
      });
      if (!user) throw new NotFoundException('ไม่พบผู้ใช้');
      if (id === actor.id)
        throw new ConflictException('ไม่สามารถปิดบัญชีที่กำลังใช้งาน');
      const updated = await tx.user.update({
        where: { id },
        data: { is_active: !user.is_active },
        select: { id: true, is_active: true },
      });
      await this.audit(tx, actor, 'User', id, user, updated);
      return updated;
    });
  }
  async updateUser(
    id: string,
    dto: Partial<CreateUserDto> & { is_active?: boolean },
    actor: Actor,
  ) {
    return this.prisma.$transaction(async (tx) => {
      await lockEntity(tx, `user:${id}`);
      const old = await tx.user.findUnique({
        where: { id },
        select: safeUserSelect,
      });
      if (!old) throw new NotFoundException('ไม่พบผู้ใช้');
      if (id === actor.id && dto.is_active === false)
        throw new ConflictException('ไม่สามารถปิดบัญชีที่กำลังใช้งาน');
      await this.references(tx, dto);
      const updated = await tx.user.update({
        where: { id },
        data: {
          email: dto.email,
          first_name: dto.first_name,
          last_name: dto.last_name,
          role_id: dto.role_id,
          department_id: dto.department_id,
          position_id: dto.position_id,
          is_active: dto.is_active,
        },
        select: safeUserSelect,
      });
      await this.audit(tx, actor, 'User', id, old, updated);
      return updated;
    });
  }
  async resetUserPassword(id: string, raw: string, actor: Actor) {
    if (typeof raw !== 'string' || raw.length < 8 || raw.length > 72)
      throw new BadRequestException('รหัสผ่านต้องยาว 8–72 ตัวอักษร');
    const hash = await bcrypt.hash(raw, 10);
    return this.prisma.$transaction(async (tx) => {
      await tx.user.update({
        where: { id },
        data: {
          password_hash: hash,
          reset_token: null,
          reset_token_expiry: null,
        },
      });
      await this.audit(tx, actor, 'User', id, {}, { password_reset: true });
      return { success: true };
    });
  }
  async getRoles() {
    const list = await this.prisma.role.findMany({
      include: {
        permissions: { include: { permission: true } },
        _count: { select: { users: true } },
      },
      orderBy: { name: 'asc' },
    });
    return list.map((r) => ({
      id: r.id,
      name: r.name,
      is_active: r.is_active,
      user_count: r._count.users,
      permissions: r.permissions.map((p) => ({
        module: p.permission.module,
        action: p.permission.action,
      })),
    }));
  }
  async getRoleById(id: string) {
    const role = (await this.getRoles()).find((r) => r.id === id);
    if (!role) throw new NotFoundException('ไม่พบบทบาท');
    return role;
  }
  async createRole(name: string, actor: Actor) {
    if (!name?.trim()) throw new BadRequestException('กรุณาระบุชื่อบทบาท');
    return this.prisma.$transaction(async (tx) => {
      const r = await tx.role.create({ data: { name: name.trim() } });
      await this.audit(tx, actor, 'Role', r.id, {}, r, 'Upload');
      return r;
    });
  }
  async updateRole(
    id: string,
    dto: {
      name?: string;
      is_active?: boolean;
      permissions?: { module: string; action: string }[];
    },
    actor: Actor,
  ) {
    if (
      dto.permissions?.some(
        (p) =>
          !p.module ||
          !['view', 'create', 'edit', 'delete', 'approve'].includes(
            p.action.toLowerCase(),
          ),
      )
    )
      throw new BadRequestException('Permission ไม่ถูกต้อง');
    await this.prisma.$transaction(async (tx) => {
      await lockEntity(tx, `role:${id}`);
      const old = await tx.role.findUnique({
        where: { id },
        include: { permissions: true },
      });
      if (!old) throw new NotFoundException('ไม่พบบทบาท');
      await tx.role.update({
        where: { id },
        data: { name: dto.name?.trim(), is_active: dto.is_active },
      });
      if (dto.permissions) {
        await tx.rolePermission.deleteMany({ where: { role_id: id } });
        for (const p of [
          ...new Map(
            dto.permissions.map((p) => [`${p.module}:${p.action}`, p]),
          ).values(),
        ]) {
          const perm = await tx.permission.upsert({
            where: {
              module_action: {
                module: p.module,
                action: p.action.toLowerCase(),
              },
            },
            update: {},
            create: { module: p.module, action: p.action.toLowerCase() },
          });
          await tx.rolePermission.create({
            data: { role_id: id, permission_id: perm.id },
          });
        }
      }
      await this.audit(
        tx,
        actor,
        'Role',
        id,
        { name: old.name, is_active: old.is_active },
        dto,
      );
    });
    return this.getRoleById(id);
  }
  deleteRole(id: string, actor: Actor) {
    return this.updateRole(id, { is_active: false }, actor);
  }
  async getDepartments() {
    const rows = await this.prisma.department.findMany({
      include: {
        _count: { select: { users: { where: { is_deleted: false } } } },
      },
      orderBy: { name: 'asc' },
    });
    return rows.map((d) => ({ ...d, employeeCount: d._count.users }));
  }
  async createDepartment(name: string, actor: Actor) {
    if (!name?.trim()) throw new BadRequestException('กรุณาระบุชื่อแผนก');
    return this.prisma.$transaction(async (tx) => {
      const d = await tx.department.create({ data: { name: name.trim() } });
      await this.audit(tx, actor, 'Department', d.id, {}, d, 'Upload');
      return d;
    });
  }
  async updateDepartment(
    id: string,
    dto: { name?: string; is_active?: boolean },
    actor: Actor,
  ) {
    return this.prisma.$transaction(async (tx) => {
      const old = await tx.department.findUnique({ where: { id } });
      if (!old) throw new NotFoundException('ไม่พบแผนก');
      const d = await tx.department.update({
        where: { id },
        data: { name: dto.name?.trim(), is_active: dto.is_active },
      });
      await this.audit(tx, actor, 'Department', id, old, d);
      return d;
    });
  }
  deleteDepartment(id: string, actor: Actor) {
    return this.updateDepartment(id, { is_active: false }, actor);
  }
  getPositions() {
    return this.prisma.position.findMany({
      include: {
        _count: { select: { users: { where: { is_deleted: false } } } },
      },
      orderBy: { name: 'asc' },
    });
  }
  async createPosition(dto: { name: string; level?: string }, actor: Actor) {
    if (!dto.name?.trim())
      throw new BadRequestException('กรุณาระบุชื่อตำแหน่ง');
    return this.prisma.$transaction(async (tx) => {
      const p = await tx.position.create({
        data: { name: dto.name.trim(), level: dto.level ?? 'L1' },
      });
      await this.audit(tx, actor, 'Position', p.id, {}, p, 'Upload');
      return p;
    });
  }
  async updatePosition(
    id: string,
    dto: { name?: string; level?: string; is_active?: boolean },
    actor: Actor,
  ) {
    return this.prisma.$transaction(async (tx) => {
      const old = await tx.position.findUnique({ where: { id } });
      if (!old) throw new NotFoundException('ไม่พบตำแหน่ง');
      const p = await tx.position.update({ where: { id }, data: dto });
      await this.audit(tx, actor, 'Position', id, old, p);
      return p;
    });
  }
  deletePosition(id: string, actor: Actor) {
    return this.updatePosition(id, { is_active: false }, actor);
  }
  async getDocumentTypes() {
    const rows = await this.prisma.documentType.findMany({
      include: {
        running_numbers: true,
        _count: { select: { documents: true } },
      },
      orderBy: { created_at: 'asc' },
    });
    return rows.map((r) => ({ ...r, doc_count: r._count.documents }));
  }
  async createDocumentType(
    dto: { type_name: string; prefix: string },
    actor: Actor,
  ) {
    if (!dto.type_name?.trim() || !/^[A-Z0-9]{2,12}$/.test(dto.prefix))
      throw new BadRequestException('ชื่อหรือ prefix ไม่ถูกต้อง');
    return this.prisma.$transaction(async (tx) => {
      const d = await tx.documentType.create({
        data: { type_name: dto.type_name.trim(), prefix: dto.prefix },
      });
      await tx.runningNumber.create({
        data: { document_type_id: d.id, prefix: d.prefix, year_format: 'YYYY' },
      });
      await this.audit(tx, actor, 'Document Type', d.id, {}, d, 'Upload');
      return d;
    });
  }
  async updateDocumentType(
    id: string,
    dto: { type_name?: string; prefix?: string; is_active?: boolean },
    actor: Actor,
  ) {
    return this.prisma.$transaction(async (tx) => {
      await lockEntity(tx, `number:${id}`);
      const old = await tx.documentType.findUnique({ where: { id } });
      if (!old) throw new NotFoundException('ไม่พบประเภทเอกสาร');
      if (dto.prefix && !/^[A-Z0-9]{2,12}$/.test(dto.prefix))
        throw new BadRequestException('Prefix ไม่ถูกต้อง');
      if (
        dto.prefix &&
        dto.prefix !== old.prefix &&
        (await tx.document.count({ where: { type_id: id } }))
      )
        throw new ConflictException(
          'มีเอกสารใช้ prefix เดิมแล้ว ไม่สามารถเปลี่ยน',
        );
      const d = await tx.documentType.update({ where: { id }, data: dto });
      if (dto.prefix)
        await tx.runningNumber.updateMany({
          where: { document_type_id: id },
          data: { prefix: dto.prefix },
        });
      await this.audit(tx, actor, 'Document Type', id, old, d);
      return d;
    });
  }
  getApprovalMatrix() {
    return this.prisma.approvalMatrix.findMany({
      include: { document_type: true, required_role: true },
      orderBy: [{ document_type_id: 'asc' }, { step_order: 'asc' }],
    });
  }
  async getApprovalWorkflows() {
    const list = await this.prisma.documentType.findMany({
      include: {
        approval_matrix: {
          include: { required_role: true },
          orderBy: { step_order: 'asc' },
        },
      },
    });
    return list.map((t) => ({
      id: t.id,
      documentTypeId: t.id,
      name: t.type_name,
      prefix: t.prefix,
      levels: t.approval_matrix.length,
      approverCount: t.approval_matrix.length,
      approvers: t.approval_matrix.map((m) => m.required_role.name),
      steps: t.approval_matrix.map((m) => m.required_role.name),
      isActive: t.is_active,
    }));
  }
  async updateApprovalWorkflow(
    id: string,
    dto: { levels?: number; steps?: string[]; is_active?: boolean },
    actor: Actor,
  ) {
    return this.prisma.$transaction(async (tx) => {
      await lockEntity(tx, `matrix:${id}`);
      const type = await tx.documentType.findUnique({ where: { id } });
      if (!type) throw new NotFoundException('ไม่พบประเภทเอกสาร');
      const old = await tx.approvalMatrix.findMany({
        where: { document_type_id: id },
        orderBy: { step_order: 'asc' },
      });
      if (dto.steps) {
        if (
          !Number.isInteger(dto.levels) ||
          dto.levels! < 1 ||
          dto.levels! > 20 ||
          dto.steps.length !== dto.levels
        )
          throw new BadRequestException('จำนวนขั้นไม่ตรงรายชื่อบทบาท');
        const roles = await tx.role.findMany({
          where: { name: { in: dto.steps }, is_active: true },
        });
        if (dto.steps.some((name) => !roles.some((r) => r.name === name)))
          throw new BadRequestException('กรุณาเลือกบทบาทที่เปิดใช้งาน');
        await tx.approvalMatrix.deleteMany({ where: { document_type_id: id } });
        await tx.approvalMatrix.createMany({
          data: dto.steps.map((name, i) => ({
            document_type_id: id,
            step_order: i + 1,
            required_role_id: roles.find((r) => r.name === name)!.id,
          })),
        });
      }
      // A disabled workflow cannot be submitted: disable its document type atomically.
      if (dto.is_active !== undefined)
        await tx.documentType.update({
          where: { id },
          data: { is_active: dto.is_active },
        });
      await this.audit(tx, actor, 'Approval Matrix', id, old, dto);
      return { success: true };
    });
  }
  async getSignatures() {
    const users = await this.prisma.user.findMany({
      where: { is_deleted: false },
      include: {
        position: true,
        _count: {
          select: { workflow_steps: { where: { signature_applied: true } } },
        },
      },
    });
    return users.map((u) => ({
      id: u.id,
      approverName: `${u.first_name} ${u.last_name}`,
      position: u.position?.name ?? '',
      signedCount: u._count.workflow_steps,
      isActive: !!u.signature_encrypted,
      imageUrl: u.signature_encrypted ? `/api/users/${u.id}/signature` : null,
    }));
  }
  async getRunningNumbers() {
    const rows = await this.prisma.runningNumber.findMany({
      include: { document_type: true },
      orderBy: { prefix: 'asc' },
    });
    return rows.map((r) => {
      let config = {
        yearFormat: r.year_format === 'YY' ? 'ce2' : 'ce4',
        separator: '-',
        resetCycle: 'yearly',
        isActive: true,
      };
      try {
        if (r.year_format.startsWith('{'))
          config = { ...config, ...JSON.parse(r.year_format) };
      } catch {
        /* legacy format */
      }
      return {
        id: r.id,
        documentTypeId: r.document_type_id,
        matrixKey: r.id,
        prefix: r.prefix,
        typeName: r.document_type.type_name,
        currentCounter: r.current_number,
        runningDigits: r.padding_length,
        ...config,
      };
    });
  }
  async updateRunningNumber(
    id: string,
    dto: {
      yearFormat?: string;
      separator?: string;
      resetCycle?: string;
      isActive?: boolean;
      current_number?: number;
      padding_length?: number;
      runningDigits?: number;
      last_reset_year?: string | number;
    },
    actor: Actor,
  ) {
    return this.prisma.$transaction(async (tx) => {
      const row = await tx.runningNumber.findUnique({ where: { id } });
      if (!row) throw new NotFoundException('ไม่พบรูปแบบเลข');
      await lockEntity(tx, `number:${row.document_type_id}`);
      if (
        dto.current_number !== undefined &&
        (!Number.isInteger(dto.current_number) ||
          dto.current_number < row.current_number)
      )
        throw new BadRequestException('ไม่สามารถลดเลข running เดิม');
      let config = {
        yearFormat: row.year_format === 'YY' ? 'ce2' : 'ce4',
        separator: '-',
        resetCycle: 'yearly',
        isActive: true,
      };
      if (row.year_format.startsWith('{'))
        config = { ...config, ...JSON.parse(row.year_format) };
      if (dto.yearFormat !== undefined) {
        if (!['ce4', 'ce2', 'be4', 'be2', 'none'].includes(dto.yearFormat))
          throw new BadRequestException('รูปแบบปีไม่ถูกต้อง');
        config.yearFormat = dto.yearFormat;
      }
      if (dto.separator !== undefined) {
        if (!['-', 'none'].includes(dto.separator))
          throw new BadRequestException('ใช้ตัวคั่น - หรือไม่มีตัวคั่น');
        config.separator = dto.separator;
      }
      if (dto.resetCycle !== undefined) {
        if (!['yearly', 'monthly', 'never'].includes(dto.resetCycle))
          throw new BadRequestException('รอบ reset ไม่ถูกต้อง');
        config.resetCycle = dto.resetCycle;
      }
      if (dto.isActive !== undefined) config.isActive = dto.isActive;
      const digits =
        dto.runningDigits ?? dto.padding_length ?? row.padding_length;
      if (!Number.isInteger(digits) || digits < 3 || digits > 8)
        throw new BadRequestException('จำนวนหลักต้องเป็น 3–8');
      const year =
        dto.last_reset_year === undefined
          ? undefined
          : Number(dto.last_reset_year);
      if (year !== undefined && !Number.isInteger(year))
        throw new BadRequestException('ปี reset ไม่ถูกต้อง');
      const updated = await tx.runningNumber.update({
        where: { id },
        data: {
          year_format: JSON.stringify(config),
          padding_length: digits,
          current_number: dto.current_number,
          ...(year !== undefined ? { last_reset_year: year } : {}),
        },
      });
      await this.audit(tx, actor, 'Running Number', id, row, updated);
      return { success: true };
    });
  }
  async createApprovalMatrixStep(
    dto: {
      document_type_id: string;
      step_order: number;
      approver_role_id: string;
    },
    actor: Actor,
  ) {
    const matrix = await this.getApprovalMatrix();
    const type = matrix
      .filter((m) => m.document_type_id === dto.document_type_id)
      .sort((a, b) => a.step_order - b.step_order);
    if (dto.step_order !== type.length + 1)
      throw new BadRequestException('เพิ่มได้เฉพาะขั้นถัดไป');
    const role = await this.prisma.role.findUnique({
      where: { id: dto.approver_role_id },
    });
    if (!role) throw new BadRequestException('ไม่พบบทบาท');
    return this.updateApprovalWorkflow(
      dto.document_type_id,
      {
        levels: type.length + 1,
        steps: [...type.map((m) => m.required_role.name), role.name],
      },
      actor,
    );
  }
  async updateApprovalMatrixStep(
    id: string,
    dto: { step_order?: number; approver_role_id?: string },
    actor: Actor,
  ) {
    const matrix = await this.getApprovalMatrix();
    const step = matrix.find((m) => m.id === id);
    if (!step) throw new NotFoundException('ไม่พบขั้น');
    if (dto.step_order !== undefined && dto.step_order !== step.step_order)
      throw new BadRequestException('แก้ลำดับผ่านหน้าสายอนุมัติ');
    const roles = await this.prisma.role.findMany();
    const entries = matrix
      .filter((m) => m.document_type_id === step.document_type_id)
      .sort((a, b) => a.step_order - b.step_order);
    const role = roles.find(
      (r) => r.id === (dto.approver_role_id ?? step.required_role_id),
    );
    if (!role) throw new BadRequestException('ไม่พบบทบาท');
    return this.updateApprovalWorkflow(
      step.document_type_id,
      {
        levels: entries.length,
        steps: entries.map((m) =>
          m.id === id ? role.name : m.required_role.name,
        ),
      },
      actor,
    );
  }
  async getAuditLogs(
    search?: string,
    action?: string,
    dateFrom?: string,
    dateTo?: string,
  ) {
    const logs = await this.prisma.auditLog.findMany({
      where: {
        ...(action && action !== 'All'
          ? { action: action as AuditAction }
          : {}),
        ...(dateFrom || dateTo
          ? {
              created_at: {
                ...(dateFrom ? { gte: new Date(dateFrom) } : {}),
                ...(dateTo
                  ? {
                      lte: (() => {
                        const d = new Date(dateTo);
                        d.setHours(23, 59, 59, 999);
                        return d;
                      })(),
                    }
                  : {}),
              },
            }
          : {}),
        ...(search
          ? {
              OR: [
                { module: { contains: search, mode: 'insensitive' as const } },
                {
                  target_id: { contains: search, mode: 'insensitive' as const },
                },
                {
                  user: {
                    is: {
                      first_name: {
                        contains: search,
                        mode: 'insensitive' as const,
                      },
                    },
                  },
                },
                {
                  user: {
                    is: {
                      last_name: {
                        contains: search,
                        mode: 'insensitive' as const,
                      },
                    },
                  },
                },
                {
                  user: {
                    is: {
                      username: {
                        contains: search,
                        mode: 'insensitive' as const,
                      },
                    },
                  },
                },
              ],
            }
          : {}),
      },
      orderBy: {
        created_at: 'desc',
      },
      include: {
        user: true,
      },
      take: 100,
    });

    return logs.map((l) => {
      let comment = '';
      let targetLabel = l.target_id;

      const details = l.details as Record<string, unknown> | null;
      if (details) {
        const extra = details.extra as Record<string, unknown> | undefined;
        if (extra?.comment) {
          comment = extra.comment as string;
        }
        if (extra?.doc_number) {
          targetLabel = extra.doc_number as string;
        } else if (l.module === 'Auth') {
          targetLabel = l.user?.username || 'System';
        }
      }

      return {
        id: l.id,
        user_id: l.user_id,
        username: l.user?.username || 'System',
        user_fullname: l.user
          ? `${l.user.first_name} ${l.user.last_name}`
          : 'ระบบ',
        action: l.action,
        module: l.module,
        target_id: l.target_id,
        target_label: targetLabel,
        comment: comment,
        ip_address: l.ip_address || '127.0.0.1',
        created_at: l.created_at,
      };
    });
  }
}

import {
  BadRequestException,
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Post,
  Put,
  Query,
  Req,
  Res,
  UploadedFile,
  UseGuards,
  UseInterceptors,
  ParseFilePipe,
  MaxFileSizeValidator,
  FileTypeValidator,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { plainToInstance } from 'class-transformer';
import { validateOrReject } from 'class-validator';
import type { Request, Response } from 'express';
import { DocumentsService } from './documents.service';
import { CreateDocumentDto } from './dto/create-document.dto';
import { JwtAuthGuard } from '../auth/jwt-auth.guard';
import { CurrentUser } from '../auth/current-user.decorator';
import { permissions, requirePermission } from '../common/document-policy';
import type { Actor } from '../common/document-policy';

const pdfPipe = new ParseFilePipe({
  validators: [
    new MaxFileSizeValidator({ maxSize: 20 * 1024 * 1024 }),
    new FileTypeValidator({ fileType: 'application/pdf' }),
  ],
});

@UseGuards(JwtAuthGuard)
@Controller('documents')
export class DocumentsController {
  constructor(private readonly documentsService: DocumentsService) {}

  @Get()
  findAll(
    @CurrentUser() user: Actor,
    @Query('status') status?: string,
    @Query('type') type?: string,
    @Query('search') search?: string,
    @Query('page') page?: number,
    @Query('limit') limit?: number,
  ) {
    return this.documentsService.findAll({
      status,
      type,
      search,
      page,
      limit,
      currentUserId: user.id,
    });
  }

  @Get(':id')
  async findOne(
    @Param('id') id: string,
    @CurrentUser() user: Actor,
    @Req() request: Request,
  ) {
    const doc = await this.documentsService.findOne(id, user);
    await this.documentsService.logAction(
      user.id,
      'View',
      doc.real_id,
      request.ip ?? '',
      doc.doc_number,
    );
    return doc;
  }

  @Get(':id/versions')
  async versions(@Param('id') id: string, @CurrentUser() user: Actor) {
    requirePermission(user, permissions.history);
    return (await this.documentsService.findOne(id, user)).versions;
  }

  @Get(':id/signed-url')
  signedUrl(@Param('id') id: string, @CurrentUser() user: Actor) {
    return this.documentsService.getLatestVersionDownloadUrl(id, user);
  }

  @Get(':id/download')
  async download(
    @Param('id') id: string,
    @CurrentUser() user: Actor,
    @Res() response: Response,
    @Req() request: Request,
    @Query('v') version?: string,
    @Query('download') download?: string,
  ) {
    const { buffer, filename } = await this.documentsService.getFileBuffer(
      id,
      version === undefined ? undefined : Number(version),
      user,
      !(download === 'true' || download === '1'),
    );
    const doc = await this.documentsService.getDocument(id);
    await this.documentsService.logAction(
      user.id,
      'Download',
      doc.id,
      request.ip ?? '',
      doc.doc_number,
    );
    response.setHeader('Content-Type', 'application/pdf');
    response.setHeader('Cache-Control', 'private, no-store');
    response.setHeader(
      'Content-Disposition',
      `${download === 'true' || download === '1' ? 'attachment' : 'inline'}; filename="document.pdf"; filename*=UTF-8''${encodeURIComponent(filename)}`,
    );
    response.send(buffer);
  }

  @Get(':id/versions/:version/signatures/:step')
  async signature(
    @Param('id') id: string,
    @Param('version') version: string,
    @Param('step') step: string,
    @CurrentUser() user: Actor,
    @Res() response: Response,
  ) {
    const image = await this.documentsService.getVersionSignature(
      id,
      Number(version),
      Number(step),
      user,
    );
    response.setHeader('Content-Type', image.mimeType);
    response.setHeader('Cache-Control', 'private, no-store');
    response.setHeader('X-Content-Type-Options', 'nosniff');
    response.send(image.buffer);
  }

  @Post()
  create(@Body() dto: CreateDocumentDto, @CurrentUser() user: Actor) {
    return this.documentsService.create(dto, user.id);
  }

  private async uploadDto(
    body: Record<string, string>,
  ): Promise<CreateDocumentDto> {
    try {
      const value = body.payload
        ? JSON.parse(body.payload)
        : {
            ...body,
            prefix: body.prefix || 'DOC',
            items: body.items ? JSON.parse(body.items) : undefined,
            visibility: body.visibility
              ? JSON.parse(body.visibility)
              : undefined,
          };
      const dto = plainToInstance(CreateDocumentDto, value);
      await validateOrReject(dto, {
        whitelist: true,
        forbidNonWhitelisted: true,
      });
      return dto;
    } catch {
      throw new BadRequestException('ข้อมูลเอกสารไม่ถูกต้อง');
    }
  }

  @Post('upload')
  @UseInterceptors(
    FileInterceptor('file', { limits: { fileSize: 20 * 1024 * 1024 } }),
  )
  async upload(
    @UploadedFile(pdfPipe) file: Express.Multer.File,
    @Body() body: Record<string, string>,
    @CurrentUser() user: Actor,
  ) {
    return this.documentsService.createWithFile(
      await this.uploadDto(body),
      user.id,
      file,
    );
  }

  @Put(':id')
  update(
    @Param('id') id: string,
    @Body() dto: CreateDocumentDto,
    @CurrentUser() user: Actor,
  ) {
    return this.documentsService.updateDocumentFull(id, dto, user.id);
  }

  @Put(':id/upload')
  @UseInterceptors(
    FileInterceptor('file', { limits: { fileSize: 20 * 1024 * 1024 } }),
  )
  async updateUpload(
    @Param('id') id: string,
    @UploadedFile(pdfPipe) file: Express.Multer.File,
    @Body() body: Record<string, string>,
    @CurrentUser() user: Actor,
  ) {
    return this.documentsService.updateDocumentFullWithFile(
      id,
      await this.uploadDto(body),
      user.id,
      file,
    );
  }

  @Post(':id/upload-new-version')
  @UseInterceptors(
    FileInterceptor('file', { limits: { fileSize: 20 * 1024 * 1024 } }),
  )
  uploadVersion(
    @Param('id') id: string,
    @UploadedFile(pdfPipe) file: Express.Multer.File,
    @Body() body: { title?: string; remarks?: string },
    @CurrentUser() user: Actor,
  ) {
    return this.documentsService.uploadNewVersion(
      id,
      user.id,
      file,
      body.title,
      body.remarks,
    );
  }

  @Post(':id/cancel')
  cancel(
    @Param('id') id: string,
    @Body() body: { reason?: string },
    @CurrentUser() user: Actor,
  ) {
    return this.documentsService.cancel(
      id,
      user,
      String(body.reason ?? '').slice(0, 5000),
    );
  }

  @Delete(':id')
  remove(@Param('id') id: string, @CurrentUser() user: Actor) {
    return this.documentsService.softDelete(id, user);
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
  ForbiddenException,
  ConflictException,
  ServiceUnavailableException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateDocumentDto } from './dto/create-document.dto';
import { Prisma, AuditAction, DocumentStatus } from '@prisma/client';
import * as fs from 'fs';
import * as path from 'path';
import puppeteer from 'puppeteer-core';
import { EncryptionService } from '../common/encryption/encryption.service';
import {
  Actor,
  hasAny,
  jsonSnapshot,
  loadActor,
  lockEntity,
  permissions,
  requireDocumentAccess,
  requireDocumentOwner,
  requirePermission,
  visibleDocuments,
} from '../common/document-policy';

const documentInclude = {
  type: true,
  creator: { include: { department: true, position: true, role: true } },
  pr_form: { include: { items: true, department: true } },
  po_form: { include: { items: true } },
  bk_form: { include: { department: true } },
  versions: {
    include: { uploaded_by: { select: { first_name: true, last_name: true } } },
    orderBy: { version_number: 'desc' as const },
  },
  workflow: {
    include: {
      steps: {
        include: { approver: { include: { role: true } } },
        orderBy: { step_order: 'asc' as const },
      },
    },
  },
} satisfies Prisma.DocumentInclude;
type FullDocument = Prisma.DocumentGetPayload<{
  include: typeof documentInclude;
}>;
export interface FindAllOptions {
  status?: string;
  type?: string;
  search?: string;
  page?: number;
  limit?: number;
  currentUserId?: string;
  currentUserRole?: string;
  permissions?: string[];
}

@Injectable()
export class DocumentsService {
  constructor(
    private prisma: PrismaService,
    private encryption: EncryptionService,
  ) {}

  async actor(user: Actor | string): Promise<Actor> {
    return typeof user === 'string' ? loadActor(this.prisma, user) : user;
  }

  async logAction(
    userId: string,
    action: AuditAction,
    targetId: string,
    ipAddress: string,
    docNumber?: string,
  ) {
    await this.prisma.auditLog.create({
      data: {
        user_id: userId,
        action,
        module: 'Document',
        target_id: targetId,
        ip_address: ipAddress,
        details: {
          oldState: {},
          newState: {},
          extra: { doc_number: docNumber },
        },
      },
    });
  }

  async findAll(options: FindAllOptions) {
    if (!options.currentUserId)
      throw new ForbiddenException('กรุณาเข้าสู่ระบบ');
    const actor = await loadActor(this.prisma, options.currentUserId);
    requirePermission(actor, permissions.view);
    const page = Number(options.page ?? 1),
      take = Number(options.limit ?? 20);
    if (
      !Number.isInteger(page) ||
      page < 1 ||
      !Number.isInteger(take) ||
      take < 1 ||
      take > 1000
    )
      throw new BadRequestException('page/limit ไม่ถูกต้อง');
    if (
      options.status &&
      options.status !== 'All' &&
      !Object.values(DocumentStatus).includes(options.status as DocumentStatus)
    )
      throw new BadRequestException('สถานะไม่ถูกต้อง');
    const where: Prisma.DocumentWhereInput = {
      AND: [
        visibleDocuments(actor),
        ...(options.status && options.status !== 'All'
          ? [{ status: options.status as DocumentStatus }]
          : []),
        ...(options.type && options.type !== 'All'
          ? [
              {
                type: {
                  prefix: options.type === 'OTHER' ? 'DOC' : options.type,
                },
              },
            ]
          : []),
        ...(options.search
          ? [
              {
                OR: [
                  {
                    title: {
                      contains: options.search,
                      mode: 'insensitive' as const,
                    },
                  },
                  {
                    doc_number: {
                      contains: options.search,
                      mode: 'insensitive' as const,
                    },
                  },
                  {
                    search_text: {
                      contains: options.search,
                      mode: 'insensitive' as const,
                    },
                  },
                ],
              },
            ]
          : []),
      ],
    };
    const [total, docs] = await Promise.all([
      this.prisma.document.count({ where }),
      this.prisma.document.findMany({
        where,
        include: documentInclude,
        orderBy: { created_at: 'desc' },
        take,
        skip: (page - 1) * take,
      }),
    ]);
    return {
      data: docs.map((d) => this.mapDocumentToResponse(d, actor)),
      meta: { total, page, limit: take, totalPages: Math.ceil(total / take) },
    };
  }

  async getDocument(
    id: string,
    database: Prisma.TransactionClient | PrismaService = this.prisma,
  ) {
    const doc = await database.document.findFirst({
      where: { OR: [{ id }, { doc_number: id }], is_deleted: false },
      include: documentInclude,
    });
    if (!doc) throw new NotFoundException('ไม่พบเอกสาร');
    return doc;
  }

  async findOne(id: string, user: Actor | string) {
    const actor = await this.actor(user),
      doc = await this.getDocument(id);
    requirePermission(actor, permissions.detail);
    requireDocumentAccess(doc, actor);
    return this.mapDocumentToResponse(doc, actor);
  }

  private async visibility(
    dto: CreateDocumentDto,
    actor: Actor,
    tx: Prisma.TransactionClient,
  ) {
    const value = dto.visibility ?? {
      type: 'CompanyWide',
      departments: [],
      users: [],
    };
    const departments = [...new Set(value.departments ?? [])],
      users = [...new Set(value.users ?? [])];
    if (value.type === 'Department' && !departments.length)
      throw new BadRequestException('กรุณาเลือกแผนกที่เข้าถึงเอกสาร');
    if (value.type === 'SpecificUsers' && !users.length)
      throw new BadRequestException('กรุณาเลือกผู้ใช้ที่เข้าถึงเอกสาร');
    if (
      departments.length &&
      (await tx.department.count({
        where: { id: { in: departments }, is_active: true },
      })) !== departments.length
    )
      throw new BadRequestException('แผนกที่เลือกไม่ถูกต้อง');
    if (
      users.length &&
      (await tx.user.count({
        where: { id: { in: users }, is_active: true, is_deleted: false },
      })) !== users.length
    )
      throw new BadRequestException('ผู้ใช้ที่เลือกไม่ถูกต้อง');
    return {
      visibility_type: value.type,
      visibility_departments: value.type === 'Department' ? departments : [],
      visibility_users:
        value.type === 'SpecificUsers'
          ? [...new Set([...users, actor.id])]
          : [],
    };
  }

  private items(dto: CreateDocumentDto, prefix: string) {
    let total = 0;
    const items = (dto.items ?? []).map((item) => {
      const price = new Prisma.Decimal(item.unit_price).mul(item.quantity);
      const vat = prefix === 'PO' ? (item.vat ?? 7) : 0;
      const gross = price
        .mul(new Prisma.Decimal(1).add(new Prisma.Decimal(vat).div(100)))
        .toDecimalPlaces(2);
      total += Number(gross);
      return {
        item_name: item.item_name.trim(),
        quantity: item.quantity,
        unit: item.unit ?? 'ชิ้น',
        unit_price: item.unit_price,
        total_price: gross,
        remark: item.remark,
        ...(prefix === 'PO' ? { vat } : {}),
      };
    });
    if ((prefix === 'PR' || prefix === 'PO') && !items.length)
      throw new BadRequestException(
        'กรุณาเพิ่มรายการสินค้าอย่างน้อยหนึ่งรายการ',
      );
    if (total > 99999999.99)
      throw new BadRequestException('ยอดรวมเกินขอบเขตที่ระบบรองรับ');
    return { items, total: Math.round(total * 100) / 100 };
  }

  private async runningNumber(
    tx: Prisma.TransactionClient,
    type: { id: string; prefix: string },
  ) {
    await lockEntity(tx, `number:${type.id}`);
    let running = await tx.runningNumber.findUnique({
      where: { document_type_id: type.id },
    });
    const now = new Date(),
      year = now.getFullYear();
    if (!running)
      running = await tx.runningNumber.create({
        data: {
          document_type_id: type.id,
          prefix: type.prefix,
          year_format: 'YYYY',
          last_reset_year: year,
        },
      });
    let config = { yearFormat: 'ce4', separator: '-', resetCycle: 'yearly' };
    try {
      if (running.year_format.startsWith('{'))
        config = { ...config, ...JSON.parse(running.year_format) };
      else if (running.year_format === 'YY') config.yearFormat = 'ce2';
    } catch {
      throw new BadRequestException('รูปแบบเลขเอกสารไม่ถูกต้อง');
    }
    if ((config as typeof config & { isActive?: boolean }).isActive === false)
      throw new BadRequestException('รูปแบบเลขเอกสารนี้ถูกปิดใช้งาน');
    const resetKey =
      config.resetCycle === 'never'
        ? 0
        : config.resetCycle === 'monthly'
          ? year * 100 + now.getMonth() + 1
          : year;
    const first = running.last_reset_year !== resetKey;
    let next = first ? 1 : running.current_number + 1;
    const formattedYear =
      config.yearFormat === 'none'
        ? ''
        : String(year + (config.yearFormat.startsWith('be') ? 543 : 0)).slice(
            config.yearFormat.endsWith('2') ? -2 : 0,
          );
    const separator = config.separator === 'none' ? '' : config.separator;
    const month =
      config.resetCycle === 'monthly'
        ? String(now.getMonth() + 1).padStart(2, '0')
        : '';
    const format = (n: number) =>
      [
        running.prefix,
        formattedYear,
        month,
        String(n).padStart(running.padding_length, '0'),
      ]
        .filter(Boolean)
        .join(separator);
    // Existing records may predate the current counter or format. Never reuse their numbers.
    while (
      await tx.document.findUnique({
        where: { doc_number: format(next) },
        select: { id: true },
      })
    )
      next++;
    await tx.runningNumber.update({
      where: { id: running.id },
      data: { current_number: next, last_reset_year: resetKey },
    });
    return format(next);
  }

  snapshotDocument(
    doc: FullDocument,
    description?: string,
    previous?: any,
  ): Prisma.InputJsonValue {
    const form = doc.pr_form ?? doc.po_form ?? doc.bk_form ?? {};
    let company = {
      companyName: 'บริษัท นิสซุย (ประเทศไทย) จำกัด',
      companyAddress: '',
    };
    try {
      company = {
        ...company,
        ...JSON.parse(
          fs.readFileSync(
            path.join(process.cwd(), 'uploads/settings.json'),
            'utf8',
          ),
        ),
      };
    } catch {
      /* Defaults apply before settings are saved. */
    }
    const signer = (user: any) =>
      user
        ? {
            id: user.id,
            username: user.username,
            first_name: user.first_name,
            last_name: user.last_name,
            department: user.department,
            position: user.position,
            role: { id: user.role?.id, name: user.role?.name },
            signature_encrypted: user.signature_encrypted,
          }
        : null;
    const workflow = doc.workflow
      ? {
          ...doc.workflow,
          steps: doc.workflow.steps.map((step) => {
            const signed = previous?._meta?.workflow?.steps?.find(
              (old: { id: string; status: string }) =>
                old.id === step.id && old.status === 'Approved',
            );
            return {
              ...step,
              approver:
                step.status === 'Approved' && signed
                  ? signed.approver
                  : signer(step.approver),
            };
          }),
        }
      : null;
    return jsonSnapshot({
      ...form,
      _meta: {
        id: doc.id,
        doc_number: doc.doc_number,
        title: doc.title,
        type: doc.type,
        created_at: doc.created_at,
        updated_at: doc.updated_at,
        approved_at: doc.approved_at,
        status: doc.status,
        creator_id: doc.creator_id,
        creator:
          doc.status !== 'Draft' && previous?._meta?.creator
            ? previous._meta.creator
            : signer(doc.creator),
        workflow,
        description:
          description ?? previous?._meta?.description ?? doc.search_text ?? '',
        company:
          doc.status !== 'Draft' && previous?._meta?.company
            ? previous._meta.company
            : company,
        visibility: {
          type: doc.visibility_type,
          departments: doc.visibility_departments,
          users: doc.visibility_users,
        },
        workflow_history: previous?._meta?.workflow_history ?? [],
        annotations: previous?._meta?.annotations ?? [],
      },
    });
  }

  async preserveLegacyVersion(tx: Prisma.TransactionClient, doc: FullDocument) {
    const latest = doc.versions[0];
    if (!latest || (latest.form_data as any)?._meta) return;
    const metadata = (
      this.snapshotDocument(doc, undefined, latest.form_data) as any
    )._meta;
    metadata.legacy_snapshot = true;
    if (metadata.creator) metadata.creator.signature_encrypted = null;
    for (const step of metadata.workflow?.steps ?? []) {
      if (step.approver) step.approver.signature_encrypted = null;
    }
    const legacy =
      latest.form_data &&
      typeof latest.form_data === 'object' &&
      !Array.isArray(latest.form_data)
        ? latest.form_data
        : (doc.pr_form ?? doc.po_form ?? doc.bk_form ?? {});
    const snapshot = jsonSnapshot({ ...legacy, _meta: metadata });
    const bytes = latest.file_data?.length
      ? Buffer.from(latest.file_data)
      : await this.generateFallbackPdf(doc, { ...latest, form_data: snapshot });
    await tx.documentVersion.update({
      where: { id: latest.id },
      data: {
        form_data: snapshot,
        file_data: bytes,
        file_size: String(bytes.length),
        file_extension: 'pdf',
      },
    });
    latest.form_data = snapshot as Prisma.JsonValue;
    latest.file_data = bytes;
  }

  async appendVersion(
    tx: Prisma.TransactionClient,
    doc: FullDocument,
    userId: string,
    remarks: string,
    buffer?: Buffer,
    description?: string,
    previous?: any,
  ) {
    const latest = await tx.documentVersion.findFirst({
      where: { document_id: doc.id },
      orderBy: { version_number: 'desc' },
    });
    const snapshot = this.snapshotDocument(
      doc,
      description,
      previous ?? latest?.form_data,
    );
    const bytes =
      buffer ?? (await this.generateFallbackPdf(doc, { form_data: snapshot }));
    return tx.documentVersion.create({
      data: {
        document_id: doc.id,
        version_number: (latest?.version_number ?? 0) + 1,
        uploaded_by_id: userId,
        remarks,
        form_data: snapshot,
        file_data: bytes,
        file_size: String(bytes.length),
        file_extension: 'pdf',
      },
    });
  }

  async create(
    dto: CreateDocumentDto,
    creatorId: string,
    file?: Express.Multer.File,
  ) {
    if (!dto.title?.trim())
      throw new BadRequestException('กรุณาระบุชื่อเอกสาร');
    const actor = await loadActor(this.prisma, creatorId);
    requirePermission(actor, permissions.create);
    if (!actor.department_id)
      throw new BadRequestException('ผู้ใช้ยังไม่ได้กำหนดแผนก');
    const prefix =
      dto.prefix === 'MEMO'
        ? 'BK'
        : dto.prefix === 'OTHER'
          ? 'DOC'
          : dto.prefix.toUpperCase();
    const data = this.items(dto, prefix);
    if (!['PR', 'PO', 'BK'].includes(prefix) && !file)
      throw new BadRequestException('กรุณาแนบไฟล์ PDF');
    if (prefix === 'PO' && !dto.vendor_name?.trim())
      throw new BadRequestException('กรุณาระบุผู้ขาย');
    return this.prisma.$transaction(
      async (tx) => {
        const type = await tx.documentType.findFirst({
          where: { prefix, is_active: true },
        });
        if (!type)
          throw new BadRequestException('ประเภทเอกสารถูกปิดใช้งานหรือไม่พบ');
        const docNumber = await this.runningNumber(tx, type);
        const doc = await tx.document.create({
          data: {
            doc_number: docNumber,
            title: dto.title.trim(),
            type_id: type.id,
            creator_id: creatorId,
            status: 'Draft',
            search_text: dto.purpose ?? '',
            ...(await this.visibility(dto, actor, tx)),
            ...(prefix === 'PR'
              ? {
                  pr_form: {
                    create: {
                      requester_id: creatorId,
                      department_id: actor.department_id!,
                      purpose: dto.purpose,
                      remark: dto.remark,
                      requested_date: dto.requested_date
                        ? new Date(dto.requested_date)
                        : new Date(),
                      required_date: dto.required_date
                        ? new Date(dto.required_date)
                        : null,
                      total_amount: data.total,
                      items: { create: data.items },
                    },
                  },
                }
              : {}),
            ...(prefix === 'PO'
              ? {
                  po_form: {
                    create: {
                      vendor_name: dto.vendor_name!,
                      vendor_contact: dto.vendor_contact,
                      delivery_date: dto.delivery_date
                        ? new Date(dto.delivery_date)
                        : null,
                      payment_terms: dto.payment_terms,
                      remark: dto.remark,
                      total_amount: data.total,
                      items: { create: data.items },
                    },
                  },
                }
              : {}),
            ...(prefix === 'BK'
              ? {
                  bk_form: {
                    create: {
                      subject: dto.title,
                      detail: dto.purpose,
                      department_id: actor.department_id!,
                    },
                  },
                }
              : {}),
          },
          include: documentInclude,
        });
        await this.appendVersion(
          tx,
          doc,
          actor.id,
          'สร้างเอกสาร (ร่าง)',
          file?.buffer,
          dto.purpose,
        );
        await tx.auditLog.create({
          data: {
            user_id: actor.id,
            action: 'Upload',
            module: 'Document',
            target_id: doc.id,
            details: {
              oldState: {},
              newState: { status: 'Draft', doc_number: doc.doc_number },
              extra: {},
            },
          },
        });
        return this.mapDocumentToResponse(
          await this.getDocument(doc.id, tx),
          actor,
        );
      },
      { timeout: 60000, maxWait: 30000 },
    );
  }

  async createWithFile(
    dto: CreateDocumentDto,
    creatorId: string,
    file: Express.Multer.File,
  ) {
    return this.create(dto, creatorId, file);
  }

  async updateDocumentFull(
    id: string,
    dto: CreateDocumentDto,
    userId: string,
    file?: Express.Multer.File,
  ) {
    const actor = await loadActor(this.prisma, userId);
    requirePermission(actor, permissions.edit);
    const original = await this.getDocument(id);
    return this.prisma.$transaction(
      async (tx) => {
        await lockEntity(tx, `document:${original.id}`);
        const doc = await this.getDocument(original.id, tx);
        requireDocumentOwner(doc, actor);
        if (!['Draft', 'Returned'].includes(doc.status))
          throw new ConflictException(
            'แก้ไขได้เฉพาะร่างหรือเอกสารที่ส่งกลับแก้ไข',
          );
        const prefix = doc.type.prefix,
          data = this.items(dto, prefix);
        if (
          (dto.prefix === 'MEMO'
            ? 'BK'
            : dto.prefix === 'OTHER'
              ? 'DOC'
              : dto.prefix.toUpperCase()) !== prefix
        )
          throw new BadRequestException('ไม่สามารถเปลี่ยนประเภทเอกสารเดิม');
        if (!doc.type.is_active)
          throw new BadRequestException('ประเภทเอกสารถูกปิดใช้งาน');
        await this.preserveLegacyVersion(tx, doc);
        const update: Prisma.DocumentUncheckedUpdateInput = {
          title: dto.title.trim(),
          search_text: dto.purpose ?? '',
          status: 'Draft',
          approved_at: null,
        };
        if (dto.visibility)
          Object.assign(update, await this.visibility(dto, actor, tx));
        await tx.document.update({ where: { id: doc.id }, data: update });
        if (doc.pr_form)
          await tx.pRForm.update({
            where: { id: doc.pr_form.id },
            data: {
              purpose: dto.purpose,
              remark: dto.remark,
              requested_date: dto.requested_date
                ? new Date(dto.requested_date)
                : doc.pr_form.requested_date,
              required_date: dto.required_date
                ? new Date(dto.required_date)
                : null,
              total_amount: data.total,
              items: { deleteMany: {}, create: data.items },
            },
          });
        if (doc.po_form)
          await tx.pOForm.update({
            where: { id: doc.po_form.id },
            data: {
              vendor_name: dto.vendor_name ?? doc.po_form.vendor_name,
              vendor_contact: dto.vendor_contact,
              delivery_date: dto.delivery_date
                ? new Date(dto.delivery_date)
                : null,
              payment_terms: dto.payment_terms,
              remark: dto.remark,
              total_amount: data.total,
              items: { deleteMany: {}, create: data.items },
            },
          });
        if (doc.bk_form)
          await tx.bKForm.update({
            where: { id: doc.bk_form.id },
            data: { subject: dto.title, detail: dto.purpose },
          });
        const updated = await this.getDocument(doc.id, tx);
        // An uploaded PDF can be reused only for DOC; generated forms always render the new snapshot.
        const buffer =
          file?.buffer ??
          (!['PR', 'PO', 'BK'].includes(prefix) && doc.versions[0]?.file_data
            ? Buffer.from(doc.versions[0].file_data)
            : undefined);
        await this.appendVersion(
          tx,
          updated,
          actor.id,
          'แก้ไขเอกสาร (ร่าง)',
          buffer,
          dto.purpose,
        );
        await tx.auditLog.create({
          data: {
            user_id: actor.id,
            action: 'Edit',
            module: 'Document',
            target_id: doc.id,
            details: {
              oldState: { title: doc.title, status: doc.status },
              newState: { title: dto.title, status: 'Draft' },
              extra: {},
            },
          },
        });
        return this.mapDocumentToResponse(
          await this.getDocument(doc.id, tx),
          actor,
        );
      },
      { timeout: 60000, maxWait: 30000 },
    );
  }

  async updateDocumentFullWithFile(
    id: string,
    dto: CreateDocumentDto,
    userId: string,
    file: Express.Multer.File,
  ) {
    return this.updateDocumentFull(id, dto, userId, file);
  }

  async uploadNewVersion(
    id: string,
    userId: string,
    file: Express.Multer.File,
    title?: string,
    remarks?: string,
  ) {
    const actor = await loadActor(this.prisma, userId);
    requirePermission(actor, permissions.edit);
    const original = await this.getDocument(id);
    return this.prisma.$transaction(async (tx) => {
      await lockEntity(tx, `document:${original.id}`);
      const doc = await this.getDocument(original.id, tx);
      requireDocumentOwner(doc, actor);
      if (!['Draft', 'Returned'].includes(doc.status))
        throw new ConflictException(
          'ต้องเป็นร่างหรือส่งกลับแก้ไขก่อนอัปโหลดฉบับใหม่',
        );
      if (['PR', 'PO', 'BK'].includes(doc.type.prefix))
        throw new BadRequestException(
          'กรุณาแก้ไขข้อมูลแบบฟอร์มเพื่อสร้างฉบับใหม่',
        );
      await this.preserveLegacyVersion(tx, doc);
      await tx.document.update({
        where: { id: doc.id },
        data: {
          title: title?.trim() || doc.title,
          status: 'Draft',
          approved_at: null,
        },
      });
      await this.appendVersion(
        tx,
        await this.getDocument(doc.id, tx),
        actor.id,
        remarks || 'อัปโหลดฉบับแก้ไข',
        file.buffer,
      );
      await tx.auditLog.create({
        data: {
          user_id: actor.id,
          action: 'Upload',
          module: 'Document',
          target_id: doc.id,
          details: {
            oldState: { status: doc.status },
            newState: { status: 'Draft' },
            extra: { version: (doc.versions[0]?.version_number ?? 0) + 1 },
          },
        },
      });
      return this.mapDocumentToResponse(
        await this.getDocument(doc.id, tx),
        actor,
      );
    });
  }

  async cancel(id: string, actor: Actor, reason: string) {
    requirePermission(actor, [
      ...permissions.delete,
      'submissions.cancel_document:delete',
      'document.recall_document:edit',
    ]);
    const original = await this.getDocument(id);
    return this.prisma.$transaction(async (tx) => {
      await lockEntity(tx, `document:${original.id}`);
      const doc = await this.getDocument(original.id, tx);
      requireDocumentOwner(doc, actor);
      if (!['Draft', 'Pending', 'Returned'].includes(doc.status))
        throw new ConflictException('ไม่สามารถยกเลิกเอกสารที่สิ้นสุดแล้ว');
      await this.preserveLegacyVersion(tx, doc);
      if (doc.workflow)
        await tx.workflow.update({
          where: { id: doc.workflow.id },
          data: { status: 'Rejected' },
        });
      await tx.document.update({
        where: { id: doc.id },
        data: { status: 'Cancelled' },
      });
      const current = await this.getDocument(doc.id, tx);
      const prior = doc.versions[0];
      await this.appendVersion(
        tx,
        current,
        actor.id,
        `ยกเลิกเอกสาร: ${reason}`,
        prior?.file_data ? Buffer.from(prior.file_data) : undefined,
      );
      await tx.notification.createMany({
        data: [
          ...new Set(
            (doc.workflow?.steps ?? [])
              .filter((s) => s.status === 'Pending' && s.approver_id)
              .map((s) => s.approver_id!),
          ),
        ].map((user_id) => ({
          user_id,
          document_id: doc.id,
          message: `เอกสาร ${doc.doc_number} ถูกยกเลิกโดยผู้สร้าง`,
        })),
      });
      await tx.auditLog.create({
        data: {
          user_id: actor.id,
          action: 'Edit',
          module: 'Document',
          target_id: doc.id,
          details: {
            oldState: { status: doc.status },
            newState: { status: 'Cancelled' },
            extra: { reason },
          },
        },
      });
      return { success: true };
    });
  }

  async softDelete(id: string, actor: Actor) {
    requirePermission(actor, permissions.delete);
    const original = await this.getDocument(id);
    return this.prisma.$transaction(async (tx) => {
      await lockEntity(tx, `document:${original.id}`);
      const doc = await this.getDocument(original.id, tx);
      requireDocumentOwner(doc, actor);
      if (doc.status === 'Pending' || doc.status === 'Approved')
        throw new ConflictException(
          'ต้องยกเลิกเอกสารก่อนลบ; เอกสารอนุมัติแล้วเก็บไว้เป็นหลักฐาน',
        );
      await tx.document.update({
        where: { id: doc.id },
        data: { is_deleted: true },
      });
      await tx.auditLog.create({
        data: {
          user_id: actor.id,
          action: 'Delete',
          module: 'Document',
          target_id: doc.id,
          details: {
            oldState: { is_deleted: false },
            newState: { is_deleted: true },
            extra: {},
          },
        },
      });
      return { success: true };
    });
  }

  async getLatestVersionDownloadUrl(id: string, user: Actor) {
    const doc = await this.findOne(id, user);
    return { url: `/api/documents/${doc.real_id}/download` };
  }

  async getFileBuffer(
    id: string,
    versionNumber?: number,
    user?: Actor,
    preview = false,
  ) {
    const doc = await this.getDocument(id);
    if (user) {
      requirePermission(
        user,
        preview ? permissions.preview : permissions.download,
      );
      requireDocumentAccess(doc, user);
    }
    if (
      user &&
      versionNumber !== undefined &&
      versionNumber !== doc.versions[0]?.version_number
    )
      requirePermission(user, permissions.history);
    const version =
      versionNumber === undefined
        ? doc.versions[0]
        : doc.versions.find((v) => v.version_number === versionNumber);
    if (
      !version ||
      (versionNumber !== undefined &&
        (!Number.isInteger(versionNumber) || versionNumber < 1))
    )
      throw new NotFoundException('ไม่พบเวอร์ชันเอกสาร');
    if (
      version.version_number !== doc.versions[0]?.version_number &&
      !version.file_data?.length &&
      (!version.form_data ||
        typeof version.form_data !== 'object' ||
        !Object.keys(version.form_data).length)
    ) {
      throw new ConflictException(
        'เวอร์ชันเดิมไม่มีไฟล์หรือข้อมูลต้นฉบับที่บันทึกไว้ ไม่สามารถสร้างเอกสารย้อนหลังแทนได้',
      );
    }
    const buffer = version.file_data?.length
      ? Buffer.from(version.file_data)
      : await this.generateFallbackPdf(doc, version);
    return {
      buffer,
      filename: `${doc.doc_number}_v${version.version_number}.pdf`,
    };
  }

  async getVersionSignature(
    id: string,
    number: number,
    step: number,
    user: Actor,
  ) {
    const doc = await this.getDocument(id);
    requireDocumentAccess(doc, user);
    requirePermission(user, permissions.view);
    if (number !== doc.versions[0]?.version_number)
      requirePermission(user, permissions.history);
    const version = doc.versions.find((v) => v.version_number === number);
    const meta = (version?.form_data as any)?._meta;
    const signer =
      step === 0
        ? meta?.creator
        : meta?.workflow?.steps?.find(
            (s: any) => s.step_order === step && s.status === 'Approved',
          )?.approver;
    const uri = this.decryptSignature(signer?.signature_encrypted);
    if (!uri) throw new NotFoundException('ไม่พบลายเซ็นในเวอร์ชันนี้');
    const match = uri.match(/^data:(image\/(?:png|jpeg));base64,(.+)$/);
    if (!match) throw new NotFoundException('รูปแบบลายเซ็นไม่รองรับ');
    return { buffer: Buffer.from(match[2], 'base64'), mimeType: match[1] };
  }

  private decryptSignature(cipherText?: string | null): string | null {
    if (!cipherText) return null;
    try {
      return this.encryption.decrypt(cipherText);
    } catch {
      return null;
    }
  }

  private buildDocumentHtml(doc: any, version?: any): string {
    const snapshot = version?.form_data;
    const meta = snapshot?._meta;
    if (snapshot) {
      doc = { ...doc, ...(meta ?? {}) };
      const prefix = doc.type?.prefix;
      if (prefix === 'PR') doc.pr_form = snapshot;
      if (prefix === 'PO') doc.po_form = snapshot;
      if (prefix === 'BK') doc.bk_form = snapshot;
      if (!meta && version.version_number !== doc.versions?.[0]?.version_number)
        doc.workflow = null;
    }
    if (version && !meta) {
      doc = {
        ...doc,
        creator: doc.creator
          ? { ...doc.creator, signature_encrypted: null }
          : null,
        workflow: doc.workflow
          ? {
              ...doc.workflow,
              steps: doc.workflow.steps.map((step: any) => ({
                ...step,
                approver: step.approver
                  ? { ...step.approver, signature_encrypted: null }
                  : null,
              })),
            }
          : null,
      };
    }
    const legacyWarning =
      version && (!meta || meta.legacy_snapshot)
        ? '<div style="font-size:10px;color:#92400e;margin-bottom:8px;">เอกสารรุ่นเดิม: ไม่ได้บันทึกภาพลายเซ็นต้นฉบับของเวอร์ชันนี้</div>'
        : '';
    // Only text from trusted templates is markup; all stored user input is escaped.
    const escape = (value: any): any => {
      if (typeof value === 'string')
        return value.replace(
          /[&<>"']/g,
          (c) =>
            ({
              '&': '&amp;',
              '<': '&lt;',
              '>': '&gt;',
              '"': '&quot;',
              "'": '&#39;',
            })[c]!,
        );
      if (
        value instanceof Date ||
        value instanceof Prisma.Decimal ||
        value === null ||
        typeof value !== 'object'
      )
        return value;
      if (Array.isArray(value)) return value.map(escape);
      return Object.fromEntries(
        Object.entries(value).map(([key, item]) => [key, escape(item)]),
      );
    };
    doc = escape(doc);
    version = escape(version);
    // 1. Company Settings
    let companyName = 'บริษัท นิสซุย (ประเทศไทย) จำกัด';
    let companyAddress =
      'เลขที่ 282 (หรือ 2086) ถนนรามคำแหง แขวงหัวหมาก เขตบางกะปิ กรุงเทพมหานคร 10240';
    try {
      const settingsPath = path.join(process.cwd(), 'uploads', 'settings.json');
      if (fs.existsSync(settingsPath)) {
        const s = JSON.parse(fs.readFileSync(settingsPath, 'utf8'));
        if (s.companyName) companyName = s.companyName;
        if (s.companyAddress) companyAddress = s.companyAddress;
      }
    } catch {
      /* Company defaults apply if no saved settings exist. */
    }

    if (version?.form_data?._meta?.company) {
      companyName = version.form_data._meta.company.companyName;
      companyAddress = version.form_data._meta.company.companyAddress;
    }
    const rawPrefix =
      doc.type?.prefix ||
      (doc.doc_number || doc.id || '').split('-')[0] ||
      'DOC';
    const prefix = rawPrefix.toUpperCase();
    const docNumber = doc.doc_number || doc.id;
    const vFormData = version?.form_data || {};

    const rawDate = doc.created_at ? new Date(doc.created_at) : new Date();
    const thaiDay = rawDate.getDate();
    const thaiMonth = rawDate.getMonth() + 1;
    const thaiYear = rawDate.getFullYear() + 543;
    const docDate = `${thaiDay}/${thaiMonth}/${thaiYear}`;

    const requesterName = doc.creator
      ? `${doc.creator.first_name || ''} ${doc.creator.last_name || ''}`.trim() ||
        doc.creator.username ||
        'วิภา รักดี'
      : 'วิภา รักดี';
    const department =
      doc.creator?.department?.name ||
      doc.pr_form?.department?.name ||
      doc.bk_form?.department?.name ||
      'แผนกจัดซื้อ';
    const title = doc.title || '-';

    const isPO = prefix === 'PO';
    const isBK = prefix === 'BK' || prefix === 'MEMO';

    const primaryColor = isPO ? '#6b21a8' : '#1e40af';
    const primaryLight = isPO ? '#f3e8ff' : '#dbeafe';
    const primaryText = isPO ? '#581c87' : '#1e3a8a';
    const highlightBanner = isPO ? '#7e22ce' : '#1d4ed8';

