  async generateFallbackPdf(doc: any, version?: any): Promise<Buffer> {
    const paths = [
      ...new Set(
        [
          ...(process.env.PDF_BROWSER_PATH
            ? [process.env.PDF_BROWSER_PATH]
            : []),
          '/usr/bin/chromium',
          '/usr/bin/google-chrome',
          'C:/Program Files/Google/Chrome/Application/chrome.exe',
          'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',
        ].filter((candidate) => fs.existsSync(candidate)),
      ),
    ];
    const html = this.buildDocumentHtml(doc, version);
    for (
      let attempt = 0;
      paths.length && attempt < Math.max(2, paths.length);
      attempt++
    ) {
      let browser: Awaited<ReturnType<typeof puppeteer.launch>> | undefined;
      try {
        browser = await puppeteer.launch({
          executablePath: paths[attempt % paths.length],
          headless: true,
          timeout: 10000,
          args: [
            '--no-sandbox',
            '--disable-setuid-sandbox',
            '--disable-gpu',
            '--disable-dev-shm-usage',
          ],
        });
        const page = await browser.newPage();
        await page.setJavaScriptEnabled(false);
        await page.setRequestInterception(true);
        page.on('request', (request) => {
          if (
            request.url().startsWith('data:') ||
            request.url() === 'about:blank'
          )
            void request.continue();
          else void request.abort();
        });
        await page.setContent(html, { waitUntil: 'load', timeout: 15000 });
        return Buffer.from(
          await page.pdf({
            format: 'A4',
            printBackground: true,
            timeout: 15000,
            margin: { top: '0mm', right: '0mm', bottom: '0mm', left: '0mm' },
          }),
        );
      } catch (error) {
        console.warn(
          'PDF renderer attempt failed:',
          error instanceof Error ? error.message : 'Unknown renderer error',
        );
      } finally {
        await browser?.close().catch(() => undefined);
      }
    }
    throw new ServiceUnavailableException(
      'ไม่สามารถสร้าง PDF ได้ กรุณาตรวจสอบ Chromium/Edge ของ server',
    );
  }

  private cleanResponse(value: any): any {
    if (value === null || value === undefined || typeof value !== 'object')
      return value;
    if (value instanceof Date || value instanceof Prisma.Decimal) return value;
    if (Array.isArray(value))
      return value.map((entry) => this.cleanResponse(entry));
    const hidden = new Set([
      'password_hash',
      'reset_token',
      'reset_token_expiry',
      'signature_encrypted',
      'file_data',
    ]);
    return Object.fromEntries(
      Object.entries(value)
        .filter(([key]) => !hidden.has(key))
        .map(([key, entry]) => [key, this.cleanResponse(entry)]),
    );
  }

  private mapDocumentToResponse(doc: FullDocument, actor?: Actor) {
    const latest = doc.versions?.[0];
    const frozenUser = (user: any, number: number, step: number) =>
      user
        ? {
            ...this.cleanResponse(user),
            signature_url: user.signature_encrypted
              ? `/api/documents/${doc.id}/versions/${number}/signatures/${step}`
              : null,
          }
        : null;
    const freezeView = (data: any, number: number) => {
      const meta = data?._meta;
      if (!meta) return this.cleanResponse(data);
      return {
        ...this.cleanResponse(data),
        _meta: {
          ...this.cleanResponse(meta),
          creator: frozenUser(meta.creator, number, 0),
          workflow: meta.workflow
            ? {
                ...this.cleanResponse(meta.workflow),
                steps: (meta.workflow.steps ?? []).map((s: any) => ({
                  ...this.cleanResponse(s),
                  approver: frozenUser(s.approver, number, s.step_order),
                  signature_url:
                    s.status === 'Approved'
                      ? frozenUser(s.approver, number, s.step_order)
                          ?.signature_url
                      : null,
                })),
              }
            : null,
        },
      };
    };
    const meta = (latest?.form_data as any)?._meta;
    const creator = meta?.creator
      ? frozenUser(meta.creator, latest.version_number, 0)
      : this.cleanResponse(doc.creator);
    const workflow = doc.workflow
      ? {
          ...this.cleanResponse(doc.workflow),
          steps: doc.workflow.steps.map((s) => {
            const stored = meta?.workflow?.steps?.find(
              (entry: any) => entry.id === s.id,
            );
            const user =
              stored && latest
                ? frozenUser(
                    stored.approver,
                    latest.version_number,
                    s.step_order,
                  )
                : this.cleanResponse(s.approver);
            return {
              ...this.cleanResponse(s),
              approver: user,
              signature_url:
                s.status === 'Approved' ? user?.signature_url : null,
            };
          }),
        }
      : null;
    const type = doc.type.prefix;
    const amount = doc.pr_form?.total_amount ?? doc.po_form?.total_amount;
    return {
      id: doc.doc_number,
      real_id: doc.id,
      doc_number: doc.doc_number,
      title: doc.title,
      name: doc.title,
      type,
      doc_type: doc.type.type_name,
      folder_id: doc.folder_id,
      status: doc.status,
      is_deleted: doc.is_deleted,
      created_at: doc.created_at,
      updated_at: doc.updated_at,
      approved_at: doc.approved_at,
      submittedDate: doc.workflow?.created_at ?? null,
      amount:
        amount !== undefined
          ? `฿${Number(amount).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
          : '-',
      creator_id: doc.creator_id,
      creator,
      creator_name: `${doc.creator.first_name} ${doc.creator.last_name}`,
      sender: `${doc.creator.first_name} ${doc.creator.last_name}`,
      department: doc.creator.department?.name ?? '',
      _meta: latest
        ? freezeView(latest.form_data, latest.version_number)?._meta
        : undefined,
      purpose: meta?.description ?? doc.search_text ?? '',
      visibility: {
        type: doc.visibility_type,
        departments: doc.visibility_departments,
        users: doc.visibility_users,
      },
      pr_form: this.cleanResponse(doc.pr_form),
      po_form: this.cleanResponse(doc.po_form),
      bk_form: this.cleanResponse(doc.bk_form),
      workflow,
      has_file: !!latest?.file_data?.length,
      fileUrl: `/api/documents/${doc.id}/download`,
      approvers:
        doc.workflow?.steps.map((s) =>
          s.approver ? `${s.approver.first_name} ${s.approver.last_name}` : '',
        ) ?? [],
      versions: (actor && !hasAny(actor, permissions.history)
        ? doc.versions.slice(0, 1)
        : doc.versions
      ).map((v, i) => ({
        id: v.id,
        version_number: v.version_number,
        version: `v${v.version_number}`,
        file_size: v.file_size,
        file_size_kb: v.file_size?.endsWith('KB')
          ? parseFloat(v.file_size)
          : Number(v.file_size ?? 0) / 1024,
        file_extension: v.file_extension,
        has_file: !!v.file_data?.length,
        form_data: freezeView(v.form_data, v.version_number),
        created_at: v.created_at,
        updated_at: v.updated_at,
        uploaded_by: v.uploaded_by
          ? `${v.uploaded_by.first_name} ${v.uploaded_by.last_name}`
          : v.uploaded_by_id,
        remarks: v.remarks,
        is_active: i === 0,
        download_url: `/api/documents/${doc.id}/download?v=${v.version_number}`,
      })),
    };
  }
}

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
  BadRequestException,
  ConflictException,
} from '@nestjs/common';
import { Prisma, FolderVisibility } from '@prisma/client';
import { PrismaService } from '../prisma/prisma.service';
import { CreateFolderDto } from './dto/create-folder.dto';
import { UpdateFolderDto } from './dto/update-folder.dto';
import { MoveDocumentDto } from './dto/move-document.dto';
import {
  Actor,
  hasAny,
  lockEntity,
  permissions,
  requireDocumentAccess,
  requirePermission,
  visibleDocuments,
} from '../common/document-policy';

const folderInclude = {
  permissions: true,
  creator: {
    select: { id: true, first_name: true, last_name: true, username: true },
  },
  department: { select: { id: true, name: true } },
} satisfies Prisma.FolderInclude;
type Folder = Prisma.FolderGetPayload<{ include: typeof folderInclude }>;
@Injectable()
export class FoldersService {
  constructor(private prisma: PrismaService) {}
  private canView(folder: Folder, user: Actor) {
    if (folder.creator_id === user.id || hasAny(user, permissions.viewAll))
      return true;
    if (folder.visibility === 'CompanyWide') return true;
    if (folder.visibility === 'Department')
      return (
        !!user.department_id && folder.department_id === user.department_id
      );
    return (
      folder.visibility === 'Shared' &&
      folder.permissions.some(
        (p) =>
          p.can_view &&
          (p.user_id === user.id ||
            (!!user.department_id && p.department_id === user.department_id)),
      )
    );
  }
  private canEdit(folder: Folder, user: Actor) {
    return (
      folder.creator_id === user.id ||
      (hasAny(user, permissions.viewAll) &&
        hasAny(user, ['document.manage_folders:edit'])) ||
      folder.permissions.some(
        (p) =>
          p.can_edit &&
          (p.user_id === user.id ||
            (!!user.department_id && p.department_id === user.department_id)),
      )
    );
  }
  private async folder(
    id: string,
    user: Actor,
    tx: Prisma.TransactionClient | PrismaService = this.prisma,
  ) {
    const f = await tx.folder.findFirst({
      where: { id, is_deleted: false },
      include: folderInclude,
    });
    if (!f) throw new NotFoundException('ไม่พบโฟลเดอร์');
    if (!this.canView(f, user))
      throw new ForbiddenException('ไม่มีสิทธิ์เข้าถึงโฟลเดอร์');
    return f;
  }
  async findAll(user: Actor) {
    requirePermission(user, ['document.view_folders:view']);
    const rows = await this.prisma.folder.findMany({
      where: { is_deleted: false },
      include: {
        ...folderInclude,
        _count: {
          select: {
            documents: {
              where: { AND: [visibleDocuments(user), { status: 'Approved' }] },
            },
          },
        },
      },
      orderBy: { name: 'asc' },
    });
    return rows
      .filter((f) => this.canView(f, user))
      .map((f) => ({
        ...f,
        department_name: f.department?.name,
        creator: {
          ...f.creator,
          full_name: `${f.creator.first_name} ${f.creator.last_name}`,
        },
        document_count: f._count.documents,
        can_edit:
          this.canEdit(f, user) &&
          hasAny(user, ['document.manage_folders:edit']),
        shared_departments: f.permissions
          .filter((p) => p.department_id)
          .map((p) => p.department_id),
        shared_users: f.permissions
          .filter((p) => p.user_id)
          .map((p) => p.user_id),
      }));
  }
  async findOne(id: string, user: Actor) {
    requirePermission(user, ['document.view_folders:view']);
    const f = await this.folder(id, user);
    const documents = await this.prisma.document.findMany({
      where: {
        folder_id: id,
        status: 'Approved',
        AND: [visibleDocuments(user)],
      },
      include: {
        type: true,
        creator: { select: { id: true, first_name: true, last_name: true } },
      },
      orderBy: { created_at: 'desc' },
    });
    const children = (await this.findAll(user)).filter(
      (child) => child.parent_id === id,
    );
    return {
      ...f,
      documents,
      children,
      can_edit:
        this.canEdit(f, user) && hasAny(user, ['document.manage_folders:edit']),
    };
  }
  private async shares(
    tx: Prisma.TransactionClient,
    folderId: string,
    departments: string[] = [],
    users: string[] = [],
  ) {
    departments = [...new Set(departments)];
    users = [...new Set(users)];
    if (
      departments.length &&
      (await tx.department.count({
        where: { id: { in: departments }, is_active: true },
      })) !== departments.length
    )
      throw new BadRequestException('แผนกที่แชร์ไม่ถูกต้อง');
    if (
      users.length &&
      (await tx.user.count({
        where: { id: { in: users }, is_active: true, is_deleted: false },
      })) !== users.length
    )
      throw new BadRequestException('ผู้ใช้ที่แชร์ไม่ถูกต้อง');
    await tx.folderPermission.deleteMany({ where: { folder_id: folderId } });
    await tx.folderPermission.createMany({
      data: [
        ...departments.map((department_id) => ({
          folder_id: folderId,
          department_id,
          can_view: true,
        })),
        ...users.map((user_id) => ({
          folder_id: folderId,
          user_id,
          can_view: true,
        })),
      ],
    });
  }
  async create(dto: CreateFolderDto, user: Actor) {
    requirePermission(user, ['document.manage_folders:create']);
    if (!dto.name.trim())
      throw new BadRequestException('กรุณาระบุชื่อโฟลเดอร์');
    if (dto.visibility === 'AdminOnly' && !hasAny(user, permissions.viewAll))
      throw new ForbiddenException('ไม่มีสิทธิ์สร้างโฟลเดอร์ผู้ดูแล');
    return this.prisma.$transaction(async (tx) => {
      if (dto.parent_id) {
        const parent = await this.folder(dto.parent_id, user, tx);
        if (parent.parent_id)
          throw new BadRequestException('รองรับโฟลเดอร์สองระดับ');
        if (!this.canEdit(parent, user))
          throw new ForbiddenException('ไม่มีสิทธิ์สร้างโฟลเดอร์ย่อย');
      }
      const dept = dto.department_id ?? user.department_id;
      if (
        dto.visibility === 'Department' &&
        (!dept ||
          !(await tx.department.findFirst({
            where: { id: dept, is_active: true },
          })))
      )
        throw new BadRequestException('ไม่พบแผนกสำหรับโฟลเดอร์');
      const folder = await tx.folder.create({
        data: {
          name: dto.name.trim(),
          description: dto.description,
          color: dto.color ?? '#4F81FF',
          icon: dto.icon ?? 'folder',
          visibility: (dto.visibility as FolderVisibility) ?? 'CompanyWide',
          parent_id: dto.parent_id ?? null,
          creator_id: user.id,
          department_id: dto.visibility === 'Department' ? dept : null,
        },
      });
      if (dto.visibility === 'Shared')
        await this.shares(
          tx,
          folder.id,
          dto.shared_departments,
          dto.shared_users,
        );
      await tx.auditLog.create({
        data: {
          user_id: user.id,
          action: 'Upload',
          module: 'Folder',
          target_id: folder.id,
          details: {
            oldState: {},
            newState: { name: folder.name, visibility: folder.visibility },
            extra: {},
          },
        },
      });
      return folder;
    });
  }
  async update(id: string, dto: UpdateFolderDto, user: Actor) {
    requirePermission(user, ['document.manage_folders:edit']);
    if (dto.name !== undefined && !dto.name.trim())
      throw new BadRequestException('กรุณาระบุชื่อโฟลเดอร์');
    return this.prisma.$transaction(async (tx) => {
      await lockEntity(tx, `folder:${id}`);
      const old = await this.folder(id, user, tx);
      if (!this.canEdit(old, user))
        throw new ForbiddenException('ไม่มีสิทธิ์แก้ไขโฟลเดอร์');
      if (dto.visibility === 'AdminOnly' && !hasAny(user, permissions.viewAll))
        throw new ForbiddenException('ไม่มีสิทธิ์ตั้งโฟลเดอร์ผู้ดูแล');
      if (dto.visibility === 'Department' && !user.department_id)
        throw new BadRequestException('ไม่พบแผนก');
      const updated = await tx.folder.update({
        where: { id },
        data: {
          name: dto.name?.trim(),
          description: dto.description,
          color: dto.color,
          icon: dto.icon,
          visibility: dto.visibility,
          ...(dto.visibility === 'Department'
            ? { department_id: old.department_id ?? user.department_id }
            : {}),
        },
      });
      if (
        updated.visibility === 'Shared' &&
        (dto.shared_departments !== undefined || dto.shared_users !== undefined)
      )
        await this.shares(
          tx,
          id,
          dto.shared_departments ??
            old.permissions
              .filter((p) => p.department_id)
              .map((p) => p.department_id!),
          dto.shared_users ??
            old.permissions.filter((p) => p.user_id).map((p) => p.user_id!),
        );
      if (updated.visibility !== 'Shared')
        await tx.folderPermission.deleteMany({ where: { folder_id: id } });
      await tx.auditLog.create({
        data: {
          user_id: user.id,
          action: 'Edit',
          module: 'Folder',
          target_id: id,
          details: {
            oldState: { name: old.name, visibility: old.visibility },
            newState: { name: updated.name, visibility: updated.visibility },
            extra: {},
          },
        },
      });
      return updated;
    });
  }
  async remove(id: string, user: Actor) {
    requirePermission(user, ['document.manage_folders:delete']);
    return this.prisma.$transaction(async (tx) => {
      await lockEntity(tx, `folder:${id}`);
      const old = await this.folder(id, user, tx);
      if (!this.canEdit(old, user))
        throw new ForbiddenException('ไม่มีสิทธิ์ลบโฟลเดอร์');
      if (
        await tx.folder.count({ where: { parent_id: id, is_deleted: false } })
      )
        throw new ConflictException('กรุณาลบโฟลเดอร์ย่อยก่อน');
      await tx.document.updateMany({
        where: { folder_id: id },
        data: { folder_id: null },
      });
      await tx.folder.update({ where: { id }, data: { is_deleted: true } });
      await tx.auditLog.create({
        data: {
          user_id: user.id,
          action: 'Delete',
          module: 'Folder',
          target_id: id,
          details: {
            oldState: { is_deleted: false },
            newState: { is_deleted: true },
            extra: {},
          },
        },
      });
      return { message: 'ลบโฟลเดอร์แล้ว เอกสารยังคงอยู่ในคลัง' };
    });
  }
  async moveDocument(dto: MoveDocumentDto, user: Actor) {
    requirePermission(user, ['document.move_to_folder:edit']);
    const original = await this.prisma.document.findFirst({
      where: {
        OR: [{ id: dto.document_id }, { doc_number: dto.document_id }],
        is_deleted: false,
      },
    });
    if (!original) throw new NotFoundException('ไม่พบเอกสาร');
    return this.prisma.$transaction(async (tx) => {
      await lockEntity(tx, `document:${original.id}`);
      const doc = await tx.document.findUniqueOrThrow({
        where: { id: original.id },
        include: { workflow: { include: { steps: true } } },
      });
      requireDocumentAccess(doc, user);
      if (doc.status !== 'Approved')
        throw new ConflictException('ย้ายเข้าคลังได้หลังอนุมัติครบแล้ว');
      if (doc.creator_id !== user.id && !hasAny(user, permissions.viewAll))
        throw new ForbiddenException(
          'เฉพาะเจ้าของหรือผู้มีสิทธิ์จัดการทั้งหมด',
        );
      if (dto.target_folder_id) {
        const target = await this.folder(dto.target_folder_id, user, tx);
        if (!this.canEdit(target, user))
          throw new ForbiddenException(
            'ไม่มีสิทธิ์เพิ่มเอกสารในโฟลเดอร์ปลายทาง',
          );
      }
      await tx.document.update({
        where: { id: doc.id },
        data: { folder_id: dto.target_folder_id ?? null },
      });
      await tx.auditLog.create({
        data: {
          user_id: user.id,
          action: 'Edit',
          module: 'Folder',
          target_id: doc.id,
          details: {
            oldState: { folder_id: doc.folder_id },
            newState: { folder_id: dto.target_folder_id ?? null },
            extra: {},
          },
        },
      });
      return { message: 'ย้ายเอกสารแล้ว' };
    });
  }
}

import { Injectable, OnModuleInit, Logger } from '@nestjs/common';
import { PrismaClient } from '@prisma/client';

@Injectable()
export class PrismaService extends PrismaClient implements OnModuleInit {
  private readonly logger = new Logger(PrismaService.name);

  constructor() {
    super({
      datasources: {
        db: {
          url:
            process.env.DATABASE_URL ||
            'postgresql://postgres:folk2546@localhost:5433/dms_db?schema=public&connection_limit=50&pool_timeout=10',
        },
      },
    });
  }

  async onModuleInit() {
    const maxRetries = 5;
    const delayMs = 2000;
    for (let attempt = 1; attempt <= maxRetries; attempt++) {
      try {
        await this.$connect();
        this.logger.log('Database connected successfully');
        return;
      } catch (err) {
        this.logger.warn(
          `DB connection attempt ${attempt}/${maxRetries} failed. Retrying in ${delayMs}ms...`,
        );
        if (attempt === maxRetries) {
          this.logger.error('Could not connect to database after max retries.');
          throw err;
        }
        await new Promise((r) => setTimeout(r, delayMs));
      }
    }
  }
}

import {
  Injectable,
  BadRequestException,
  ConflictException,
  ForbiddenException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { EncryptionService } from '../common/encryption/encryption.service';
import { DocumentsService } from '../documents/documents.service';
import { ApproveStepDto } from './dto/approve-step.dto';
import { RejectStepDto, RejectType } from './dto/reject-step.dto';
import {
  Actor,
  loadActor,
  lockEntity,
  requireDocumentOwner,
  requirePermission,
  permissions,
} from '../common/document-policy';
import { PDFDocument, StandardFonts } from 'pdf-lib';
import fontkit from '@pdf-lib/fontkit';
import * as fs from 'fs';

@Injectable()
export class WorkflowsService {
  constructor(
    private prisma: PrismaService,
    private encryption: EncryptionService,
    private documents: DocumentsService,
  ) {}

  async submitWorkflow(
    documentId: string,
    userId: string,
    customSteps?: Array<{ step_order: number; approver_id?: string }>,
  ) {
    const actor = await loadActor(this.prisma, userId);
    requirePermission(actor, permissions.submit);
    const original = await this.documents.getDocument(documentId);
    return this.prisma.$transaction(
      async (tx) => {
        await lockEntity(tx, `document:${original.id}`);
        await lockEntity(tx, `matrix:${original.type_id}`);
        const doc = await this.documents.getDocument(original.id, tx);
        requireDocumentOwner(doc, actor);
        if (!['Draft', 'Returned'].includes(doc.status))
          throw new ConflictException('ส่งอนุมัติได้เฉพาะร่างหรือส่งกลับแก้ไข');
        if (!doc.type.is_active)
          throw new BadRequestException('ประเภทเอกสารถูกปิดใช้งาน');
        const matrix = await tx.approvalMatrix.findMany({
          where: { document_type_id: doc.type_id },
          include: { required_role: true },
          orderBy: { step_order: 'asc' },
        });
        if (
          !matrix.length ||
          matrix.some(
            (m, i) => m.step_order !== i + 1 || !m.required_role.is_active,
          )
        )
          throw new BadRequestException(
            'กรุณาตั้งสายอนุมัติใน Master Data ให้ครบก่อนส่ง',
          );
        if (
          customSteps &&
          (customSteps.length !== matrix.length ||
            customSteps.some((s, i) => s.step_order !== i + 1))
        )
          throw new BadRequestException('จำนวนและลำดับขั้นต้องตรง Master Data');
        const steps: {
          step_order: number;
          approver_id: string;
          status: 'Pending';
        }[] = [];
        for (const m of matrix) {
          const selected =
            customSteps?.find((s) => s.step_order === m.step_order)
              ?.approver_id ??
            doc.workflow?.steps.find((s) => s.step_order === m.step_order)
              ?.approver_id;
          if (!selected)
            throw new BadRequestException(
              `กรุณาเลือกผู้อนุมัติขั้นที่ ${m.step_order}`,
            );
          const approver = await loadActor(tx, selected);
          if (approver.role_id !== m.required_role_id)
            throw new BadRequestException(
              `ผู้อนุมัติขั้นที่ ${m.step_order} ต้องมีบทบาท ${m.required_role.name}`,
            );
          requirePermission(approver, ['approvals.approve_document:approve']);
          steps.push({
            step_order: m.step_order,
            approver_id: approver.id,
            status: 'Pending',
          });
        }
        const latest = doc.versions[0];
        if (!latest) throw new BadRequestException('ไม่พบ version เอกสาร');
        if (
          !['PR', 'PO', 'BK'].includes(doc.type.prefix) &&
          !latest.file_data?.length
        )
          throw new BadRequestException('ไม่พบไฟล์ PDF');
        await this.documents.preserveLegacyVersion(tx, doc);
        const previous = latest.form_data as any;
        const history = [
          ...(previous?._meta?.workflow_history ?? []),
          ...(doc.workflow
            ? [
                (
                  this.documents.snapshotDocument(
                    doc,
                    undefined,
                    previous,
                  ) as any
                )._meta.workflow,
              ]
            : []),
        ];
        if (doc.workflow)
          await tx.workflow.delete({ where: { id: doc.workflow.id } });
        await tx.workflow.create({
          data: {
            document_id: doc.id,
            total_steps: steps.length,
            current_step: 1,
            status: 'Pending',
            steps: { create: steps },
          },
        });
        await tx.document.update({
          where: { id: doc.id },
          data: { status: 'Pending', approved_at: null },
        });
        const current = await this.documents.getDocument(doc.id, tx);
        const retained = {
          ...previous,
          _meta: { ...previous?._meta, workflow_history: history },
        };
        const buffer = !['PR', 'PO', 'BK'].includes(doc.type.prefix)
          ? Buffer.from(latest.file_data!)
          : undefined;
        await this.documents.appendVersion(
          tx,
          current,
          actor.id,
          'ส่งขออนุมัติ',
          buffer,
          undefined,
          retained,
        );
        await tx.notification.create({
          data: {
            user_id: steps[0].approver_id,
            document_id: doc.id,
            message: `เอกสาร ${doc.doc_number} รอการอนุมัติจากคุณ (ขั้นตอนที่ 1)`,
          },
        });
        await tx.auditLog.create({
          data: {
            user_id: actor.id,
            action: 'Edit',
            module: 'Workflow',
            target_id: doc.id,
            details: {
              oldState: { status: doc.status },
              newState: { status: 'Pending' },
              extra: { total_steps: steps.length, doc_number: doc.doc_number },
            },
          },
        });
        return { success: true, doc_number: doc.doc_number, status: 'Pending' };
      },
      { timeout: 60000, maxWait: 30000 },
    );
  }

  async getApprovalsForUser(userId: string, canViewAll = false) {
    const actor = await loadActor(this.prisma, userId);
    requirePermission(actor, [
      'approvals.view_list:view',
      'approvals.view_all:view',
    ]);
    canViewAll =
      canViewAll && !!actor.permissions?.includes('approvals.view_all:view');
    const rows = await this.prisma.workflowStep.findMany({
      where: {
        status: 'Pending',
        ...(canViewAll ? {} : { approver_id: userId }),
        workflow: {
          status: 'Pending',
          document: { is_deleted: false, status: 'Pending' },
        },
      },
      include: {
        workflow: {
          include: {
            document: {
              include: {
                creator: { include: { department: true } },
                type: true,
                pr_form: true,
                po_form: true,
              },
            },
            steps: {
              include: {
                approver: { select: { first_name: true, last_name: true } },
              },
              orderBy: { step_order: 'asc' },
            },
          },
        },
      },
      orderBy: { created_at: 'desc' },
    });
    return rows
      .filter((s) => s.step_order === s.workflow.current_step)
      .map((s) => {
        const d = s.workflow.document;
        return {
          id: d.doc_number,
          real_id: d.id,
          docId: d.doc_number,
          name: d.title,
          docName: d.title,
          type: d.type.prefix,
          doc_type: d.type.type_name,
          sender: `${d.creator.first_name} ${d.creator.last_name}`,
          requester: `${d.creator.first_name} ${d.creator.last_name}`,
          department: d.creator.department?.name ?? '',
          approvers: s.workflow.steps.map((st) =>
            st.approver
              ? `${st.approver.first_name} ${st.approver.last_name}`
              : '',
          ),
          submittedDate: s.workflow.created_at,
          amount:
            d.pr_form || d.po_form
              ? `฿${Number(d.pr_form?.total_amount ?? d.po_form?.total_amount).toLocaleString()}`
              : '-',
          status: d.status,
          stepStatus: s.status,
          stepOrder: s.step_order,
          currentLevel: s.step_order,
          totalSteps: s.workflow.total_steps,
          maxLevels: s.workflow.total_steps,
          comment: s.comment,
        };
      });
  }

  async getWorkflowByDoc(documentId: string, actor: Actor) {
    const doc = await this.documents.findOne(documentId, actor);
    const workflow = doc.workflow;
    return workflow
      ? {
          id: workflow.id,
          document_id: doc.real_id,
          status: workflow.status,
          total_steps: workflow.total_steps,
          current_step: workflow.current_step,
          steps: workflow.steps.map((s: any) => ({
            id: s.id,
            step_order: s.step_order,
            approver_id: s.approver_id,
            approver_name: s.approver
              ? `${s.approver.first_name} ${s.approver.last_name}`
              : '',
            approver_role: s.approver?.role?.name ?? '',
            status: s.status,
            action_date: s.action_date,
            comment: s.comment,
            signature_applied: s.signature_applied,
            signature_url: s.signature_url,
          })),
        }
      : {
          document_id: doc.real_id,
          status: doc.status,
          total_steps: 0,
          current_step: 0,
          steps: [],
        };
  }

  private assertCurrent(
    doc: Awaited<ReturnType<DocumentsService['getDocument']>>,
    actor: Actor,
    expectedStep?: number,
    expectedVersion?: number,
  ) {
    if (doc.status !== 'Pending' || doc.workflow?.status !== 'Pending')
      throw new ConflictException('เอกสารไม่ได้อยู่ระหว่างอนุมัติ');
    const step = doc.workflow.steps.find(
      (s) => s.step_order === doc.workflow!.current_step,
    );
    if (!step || step.status !== 'Pending')
      throw new ConflictException('ขั้นอนุมัตินี้สิ้นสุดแล้ว');
    if (step.approver_id !== actor.id)
      throw new ForbiddenException('คุณไม่ใช่ผู้อนุมัติที่กำหนดในขั้นปัจจุบัน');
    if (
      (expectedStep !== undefined && expectedStep !== step.step_order) ||
      (expectedVersion !== undefined &&
        expectedVersion !== doc.versions[0]?.version_number)
    )
      throw new ConflictException('เอกสารเปลี่ยนแล้ว กรุณาโหลดข้อมูลล่าสุด');
    return step;
  }

  async approveStep(documentId: string, userId: string, dto: ApproveStepDto) {
    const actor = await loadActor(this.prisma, userId);
    requirePermission(actor, ['approvals.approve_document:approve']);
    requirePermission(actor, ['approvals.place_signature:approve']);
    const original = await this.documents.getDocument(documentId);
    return this.prisma.$transaction(
      async (tx) => {
        await lockEntity(tx, `document:${original.id}`);
        const doc = await this.documents.getDocument(original.id, tx);
        const step = this.assertCurrent(
          doc,
          actor,
          dto.expected_step,
          dto.expected_version,
        );
        const approver = await tx.user.findUnique({
          where: { id: userId },
          select: { signature_encrypted: true },
        });
        if (!approver?.signature_encrypted)
          throw new BadRequestException(
            'กรุณาบันทึกลายเซ็น PNG/JPEG ในโปรไฟล์ก่อนอนุมัติ',
          );
        let uri: string;
        try {
          uri = this.encryption.decrypt(approver.signature_encrypted);
        } catch {
          throw new BadRequestException(
            'อ่านลายเซ็นไม่ได้ กรุณาบันทึกลายเซ็นใหม่',
          );
        }
        const image = uri.match(/^data:(image\/(?:png|jpeg));base64,(.+)$/);
        if (!image)
          throw new BadRequestException('รองรับลายเซ็น PNG/JPEG เท่านั้น');
        await this.documents.preserveLegacyVersion(tx, doc);
        const imageBytes = Buffer.from(image[2], 'base64');
        try {
          const validator = await PDFDocument.create();
          if (image[1] === 'image/jpeg') await validator.embedJpg(imageBytes);
          else await validator.embedPng(imageBytes);
        } catch {
          throw new BadRequestException(
            'ลายเซ็นเสียหาย กรุณาบันทึกลายเซ็นใหม่',
          );
        }
        const completed = step.step_order === doc.workflow!.total_steps;
        let folderId = doc.folder_id;
        if (completed && !folderId && doc.creator.department_id)
          folderId =
            (
              await tx.folder.findFirst({
                where: {
                  visibility: 'Department',
                  department_id: doc.creator.department_id,
                  is_deleted: false,
                  parent_id: null,
                },
              })
            )?.id ?? null;
        await tx.workflowStep.update({
          where: { id: step.id },
          data: {
            status: 'Approved',
            action_date: new Date(),
            comment: dto.comment,
            signature_applied: true,
          },
        });
        await tx.workflow.update({
          where: { id: doc.workflow!.id },
          data: completed
            ? { status: 'Approved' }
            : { current_step: step.step_order + 1 },
        });
        await tx.document.update({
          where: { id: doc.id },
          data: {
            status: completed ? 'Approved' : 'Pending',
            ...(completed
              ? { approved_at: new Date(), folder_id: folderId }
              : {}),
          },
        });
        const current = await this.documents.getDocument(doc.id, tx);
        const previous = doc.versions[0]?.form_data as any;
        const annotations = [
          ...(previous?._meta?.annotations ?? []),
          ...(dto.annotation_text || dto.date_stamp
            ? [
                {
                  user_id: actor.id,
                  text: dto.annotation_text ?? '',
                  date: dto.date_stamp ? new Date().toISOString() : null,
                },
              ]
            : []),
        ];
        const retained = {
          ...previous,
          _meta: { ...previous?._meta, annotations },
        };
        let bytes: Buffer;
        if (['PR', 'PO', 'BK'].includes(doc.type.prefix)) {
          const snapshot = this.documents.snapshotDocument(
            current,
            undefined,
            retained,
          );
          bytes = await this.documents.generateFallbackPdf(current, {
            form_data: snapshot,
          });
        } else {
          const file = doc.versions[0]?.file_data;
          if (!file) throw new BadRequestException('ไม่พบไฟล์ PDF');
          try {
            const pdf = await PDFDocument.load(file),
              pageIndex = (dto.signature_page ?? 1) - 1;
            if (pageIndex < 0 || pageIndex >= pdf.getPageCount())
              throw new Error('หน้าลายเซ็นไม่ถูกต้อง');
            const page = pdf.getPage(pageIndex),
              width = dto.signature_width ?? 120,
              height = dto.signature_height ?? 60;
            const x = dto.signature_x ?? 36 + ((step.step_order - 1) % 3) * 170;
            const y =
              dto.signature_y ??
              60 + Math.floor((step.step_order - 1) / 3) * 90;
            if (
              x < 0 ||
              y < 0 ||
              width <= 0 ||
              height <= 0 ||
              x + width > page.getWidth() ||
              y + height > page.getHeight()
            )
              throw new Error('ลายเซ็นอยู่นอกหน้า PDF');
            const signature =
              image[1] === 'image/jpeg'
                ? await pdf.embedJpg(imageBytes)
                : await pdf.embedPng(imageBytes);
            page.drawImage(signature, { x, y, width, height });
            if (dto.annotation_text || dto.date_stamp) {
              let font = await pdf.embedFont(StandardFonts.Helvetica);
              const fontPath =
                process.env.PDF_FONT_PATH || 'C:/Windows/Fonts/tahoma.ttf';
              if (fs.existsSync(fontPath)) {
                pdf.registerFontkit(fontkit);
                font = await pdf.embedFont(fs.readFileSync(fontPath));
              }
              const text = [
                dto.annotation_text,
                dto.date_stamp
                  ? new Date().toLocaleString('th-TH', {
                      timeZone: 'Asia/Bangkok',
                    })
                  : '',
              ]
                .filter(Boolean)
                .join(' ');
              page.drawText(text, {
                x,
                y: y >= 40 ? y - 20 : y + height + 20,
                size: 9,
                font,
                maxWidth: Math.min(
                  Math.max(width, 170),
                  page.getWidth() - x - 12,
                ),
                lineHeight: 12,
              });
            }
            bytes = Buffer.from(await pdf.save());
          } catch (error) {
            throw new BadRequestException(
              `ไม่สามารถลงลายเซ็น PDF: ${error instanceof Error ? error.message : 'ไฟล์ไม่ถูกต้อง'}`,
            );
          }
        }
        const version = await this.documents.appendVersion(
          tx,
          current,
          actor.id,
          completed
            ? 'อนุมัติเสร็จสิ้น'
            : `อนุมัติขั้นตอนที่ ${step.step_order}`,
          bytes,
          undefined,
          retained,
        );
        await tx.notification.create({
          data: {
            user_id: doc.creator_id,
            document_id: doc.id,
            message: completed
              ? `เอกสาร ${doc.doc_number} ได้รับการอนุมัติครบถ้วนแล้ว`
              : `เอกสาร ${doc.doc_number} ผ่านการอนุมัติขั้นตอนที่ ${step.step_order}`,
          },
        });
        const next = current.workflow!.steps.find(
          (s) => s.step_order === step.step_order + 1,
        );
        if (!completed && next?.approver_id)
          await tx.notification.create({
            data: {
              user_id: next.approver_id,
              document_id: doc.id,
              message: `เอกสาร ${doc.doc_number} รอการอนุมัติจากคุณ (ขั้นตอนที่ ${next.step_order})`,
            },
          });
        for (const action of ['Approve', 'Signature'] as const)
          await tx.auditLog.create({
            data: {
              user_id: actor.id,
              action,
              module: 'Workflow',
              target_id: doc.id,
              details: {
                oldState: { status: doc.status, current_step: step.step_order },
                newState: {
                  status: current.status,
                  current_step: current.workflow!.current_step,
                },
                extra: {
                  doc_number: doc.doc_number,
                  version: version.version_number,
                  comment: dto.comment,
                },
              },
            },
          });
        return {
          success: true,
          is_completed: completed,
          signature_applied: true,
          new_version: version.version_number,
        };
      },
      { timeout: 60000, maxWait: 30000 },
    );
  }

  async rejectStep(documentId: string, userId: string, dto: RejectStepDto) {
    const actor = await loadActor(this.prisma, userId);
    requirePermission(actor, [
      dto.reject_type === RejectType.RETURN
        ? 'approvals.return_document:approve'
        : 'approvals.reject_document:approve',
    ]);
    const original = await this.documents.getDocument(documentId);
    return this.prisma.$transaction(
      async (tx) => {
        await lockEntity(tx, `document:${original.id}`);
        const doc = await this.documents.getDocument(original.id, tx);
        const step = this.assertCurrent(
          doc,
          actor,
          dto.expected_step,
          dto.expected_version,
        );
        await this.documents.preserveLegacyVersion(tx, doc);
        const status =
          dto.reject_type === RejectType.RETURN ? 'Returned' : 'Rejected';
        await tx.workflowStep.update({
          where: { id: step.id },
          data: {
            status: 'Rejected',
            action_date: new Date(),
            comment: dto.comment,
            return_to_step: dto.reject_type === RejectType.RETURN ? 1 : null,
          },
        });
        await tx.workflow.update({
          where: { id: doc.workflow!.id },
          data: { status: 'Rejected' },
        });
        await tx.document.update({
          where: { id: doc.id },
          data: { status, approved_at: null },
        });
        const current = await this.documents.getDocument(doc.id, tx),
          latest = doc.versions[0];
        const bytes = latest?.file_data
          ? Buffer.from(latest.file_data)
          : await this.documents.generateFallbackPdf(doc, latest);
        await this.documents.appendVersion(
          tx,
          current,
          actor.id,
          `${status === 'Returned' ? 'ตีกลับแก้ไข' : 'ไม่อนุมัติ'}: ${dto.comment}`,
          bytes,
        );
        await tx.notification.create({
          data: {
            user_id: doc.creator_id,
            document_id: doc.id,
            message: `เอกสาร ${doc.doc_number} ${status === 'Returned' ? 'ถูกส่งกลับแก้ไข' : 'ถูกปฏิเสธ'}: ${dto.comment}`,
          },
        });
        await tx.auditLog.create({
          data: {
            user_id: actor.id,
            action: 'Reject',
            module: 'Workflow',
            target_id: doc.id,
            details: {
              oldState: { status: doc.status },
              newState: { status },
              extra: { comment: dto.comment, doc_number: doc.doc_number },
            },
          },
        });
        return {
          success: true,
          doc_status: status,
          reject_type: dto.reject_type,
        };
      },
      { timeout: 60000 },
    );
  }
}
